// Core Export Function
// ============================================================================

/**
 * Exports a Keyboardia session to MIDI format.
 *
 * @param state - Grid state containing tracks, tempo, and swing
 * @param options - Export options (session name for filename)
 * @returns Filename and raw MIDI data without browser-only APIs
 */
export function encodeMidi(
  state: MidiState,
  options: MidiExportOptions = {}
): MidiEncodingResult {
  // Array of midi-writer-js Track instances
  const tracks: InstanceType<typeof MidiWriter.Track>[] = [];

  // Track 0: Tempo track with time signature and tempo meta events
  const tempoTrack = new MidiWriter.Track();
  tempoTrack.setTempo(state.tempo);
  tempoTrack.setTimeSignature(4, 4, 24, 8);
  tempoTrack.addTrackName('Tempo');
  tracks.push(tempoTrack);

  // Calculate pattern length (LCM for polyrhythms)
  const patternLength = calculatePatternLength(state.tracks);

  // Track selection: MUST match scheduler.ts logic
  // @spec: track-selection - Same as audio scheduler
  const anySoloed = state.tracks.some((t) => t.soloed);

  // Channel assignment: synths use 1-9, 11-16 (skip 10 for drums)
  let synthChannelCounter = 1;
  const getNextSynthChannel = (): number => {
    const channel = synthChannelCounter;
    synthChannelCounter++;
    if (synthChannelCounter === DRUM_CHANNEL) {
      synthChannelCounter++; // Skip drum channel
    }
    if (synthChannelCounter > 16) {
      synthChannelCounter = 1; // Wrap around (shouldn't happen with 16 tracks max)
    }
    return channel;
  };

  // Export each track
  for (const keyboardiaTrack of state.tracks) {
    // Track selection: solo wins over mute
    const shouldExport = anySoloed
      ? keyboardiaTrack.soloed
      : !keyboardiaTrack.muted;
    if (!shouldExport) continue;

    // Skip empty tracks
    if (!hasActiveSteps(keyboardiaTrack)) continue;

    const midiTrack = new MidiWriter.Track();
    midiTrack.addTrackName(keyboardiaTrack.name);

    const isDrum = isDrumTrack(keyboardiaTrack);
    const channel = isDrum ? DRUM_CHANNEL : getNextSynthChannel();

    // Add program change for synth tracks (0-indexed for MIDI)
    if (!isDrum) {
      const program = getSynthProgram(keyboardiaTrack);
      midiTrack.addEvent(
        new MidiWriter.ProgramChangeEvent({
          instrument: program - 1, // Convert 1-indexed GM to 0-indexed MIDI
          channel,
        })
      );
    }

    // Calculate how many times this track loops
    const trackStepCount = keyboardiaTrack.stepCount ?? DEFAULT_STEP_COUNT;
    const loopCount = patternLength / trackStepCount;

    // Add notes for each loop iteration
    for (let loop = 0; loop < loopCount; loop++) {
      for (let step = 0; step < trackStepCount; step++) {
        if (!keyboardiaTrack.steps[step]) continue;

        const pLock = keyboardiaTrack.parameterLocks[step];
        const absoluteStep = loop * trackStepCount + step;

        // A tied step continues the immediately preceding active step. The
        // first step in the file still needs an attack because MIDI has no note
        // before tick zero to continue from.
        const previousTrackStep = (step - 1 + trackStepCount) % trackStepCount;
        if (
          absoluteStep > 0 &&
          pLock?.tie === true &&
          keyboardiaTrack.steps[previousTrackStep]
        ) {
          continue;
        }

        const startTick = stepToTicks(absoluteStep, state.swing);
        const velocity = getVelocity(pLock);
        const pitch = isDrum
          ? getDrumNote(keyboardiaTrack)
          : getSynthNotePitch(keyboardiaTrack, pLock);

        midiTrack.addEvent(
          new MidiWriter.NoteEvent({
            pitch: [pitch],
            velocity,
            startTick,
            duration: `T${
              tiedStepCount(keyboardiaTrack, step, patternLength - absoluteStep) * TICKS_PER_STEP - 1
            }`,
            channel,
          })
        );
      }
    }

    tracks.push(midiTrack);
  }

  // Build MIDI file
  const writer = new MidiWriter.Writer(tracks);
  const midiData = writer.buildFile();

  // Convert to Uint8Array for TypeScript compatibility
  const uint8Array = new Uint8Array(midiData);

  // Generate filename
  const filename = `${sanitizeFilename(options.sessionName)}.mid`;

  return {
    filename,
    midiData: uint8Array,
  };
}

import { DEFAULT_STEP_COUNT } from './constants';

/** A deliberately generous ceiling: 1,024 bars of sixteenth notes. */
export const MAX_PATTERN_STEPS = 16_384;

/** Keeps MIDI creation bounded even when many dense tracks realign slowly. */
export const MAX_MIDI_NOTE_EVENTS = 100_000;

export interface PatternTrack {
  steps: readonly boolean[];
  stepCount?: number;
}

export class PatternExpansionError extends Error {
  readonly code = 'PATTERN_EXPANSION_TOO_LARGE';
  readonly limit: number;

  constructor(
    message: string,
    limit: number
  ) {
    super(message);
    this.name = 'PatternExpansionError';
    this.limit = limit;
  }
}

export function stepCountOf(track: PatternTrack): number {
  return track.stepCount ?? DEFAULT_STEP_COUNT;
}

/** Hidden cells beyond a shortened loop are state history, not sounding steps. */
export function activeStepCount(track: PatternTrack): number {
  return track.steps.slice(0, stepCountOf(track)).filter(Boolean).length;
}

export function hasActiveSteps(track: PatternTrack): boolean {
  return activeStepCount(track) > 0;
}

function gcd(a: number, b: number): number {
  while (b !== 0) {
    [a, b] = [b, a % b];
  }
  return a;
}

/**
 * Compute an LCM while it is still safe to do so. The division happens before
 * multiplication, and the multiplication is rejected before a huge pattern is
 * ever represented or iterated.
 */
export function boundedPatternLength(
  stepCounts: readonly number[],
  { empty = 0, limit = MAX_PATTERN_STEPS }: { empty?: number; limit?: number } = {}
): number {
  if (stepCounts.length === 0) return empty;

  let pattern = 1;
  for (const count of stepCounts) {
    const factor = count / gcd(pattern, count);
    if (factor > Math.floor(limit / pattern)) {
      throw new PatternExpansionError(
        `The combined loop is longer than the ${limit}-step safety limit. Shorten or align the track loop lengths before continuing.`,
        limit
      );
    }
    pattern *= factor;
  }
  return pattern;
}

export interface PatternExpansionPlan {
  patternSteps: number;
  noteEvents: number;
}

/**
 * Plan the complete expansion before an exporter allocates a single event.
 * Since the pattern length is an LCM, every division below is integral.
 */
export function planPatternExpansion(
  tracks: readonly PatternTrack[],
  {
    empty = DEFAULT_STEP_COUNT,
    maxPatternSteps = MAX_PATTERN_STEPS,
    maxNoteEvents = MAX_MIDI_NOTE_EVENTS,
  }: {
    empty?: number;
    maxPatternSteps?: number;
    maxNoteEvents?: number;
  } = {}
): PatternExpansionPlan {
  const patternSteps = boundedPatternLength(
    tracks.map(stepCountOf),
    { empty, limit: maxPatternSteps }
  );

  let noteEvents = 0;
  for (const track of tracks) {
    noteEvents += activeStepCount(track) * (patternSteps / stepCountOf(track));
    if (noteEvents > maxNoteEvents) {
      throw new PatternExpansionError(
        `The MIDI export would create more than ${maxNoteEvents} note events. Reduce pattern density or align the track loop lengths before exporting.`,
        maxNoteEvents
      );
    }
  }

  return { patternSteps, noteEvents };
}

/**
 * Pattern manipulation operations for 31B: Pattern Manipulation
 *
 * These operations work on step patterns (boolean arrays) and preserve
 * parameter locks during transformations.
 */

import type { ParameterLock } from './sync-types';

/** Shallow array equality — replaces JSON.stringify comparison in Bjorklund loop. */
export function arraysEqual(a: boolean[], b: boolean[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

/**
 * Rotate pattern left: Step 0 → Step N-1, Step 1 → Step 0, etc.
 * Wraps around so no steps are lost.
 */
export function rotateLeft<T>(arr: T[], stepCount: number): T[] {
  if (stepCount <= 1) return arr;
  const result = [...arr];
  // Only rotate within the active step count
  const first = result[0];
  for (let i = 0; i < stepCount - 1; i++) {
    result[i] = result[i + 1];
  }
  result[stepCount - 1] = first;
  return result;
}

/**
 * Rotate pattern right: Step N-1 → Step 0, Step 0 → Step 1, etc.
 * Wraps around so no steps are lost.
 */
export function rotateRight<T>(arr: T[], stepCount: number): T[] {
  if (stepCount <= 1) return arr;
  const result = [...arr];
  // Only rotate within the active step count
  const last = result[stepCount - 1];
  for (let i = stepCount - 1; i > 0; i--) {
    result[i] = result[i - 1];
  }
  result[0] = last;
  return result;
}

/**
 * Invert pattern: Toggle all steps (active → inactive, inactive → active)
 * Only affects steps within stepCount.
 */
export function invertPattern(steps: boolean[], stepCount: number): boolean[] {
  const result = [...steps];
  for (let i = 0; i < stepCount; i++) {
    result[i] = !result[i];
  }
  return result;
}

/**
 * Reverse pattern: Play the pattern backwards
 * Step 0 ↔ Step N-1, Step 1 ↔ Step N-2, etc.
 * Parameter locks are also reversed.
 */
export function reversePattern<T>(arr: T[], stepCount: number): T[] {
  const result = [...arr];
  // Only reverse within the active step count
  for (let i = 0; i < Math.floor(stepCount / 2); i++) {
    const temp = result[i];
    result[i] = result[stepCount - 1 - i];
    result[stepCount - 1 - i] = temp;
  }
  return result;
}

/**
 * Direction for mirror operation
 */
export type MirrorDirection = 'left-to-right' | 'right-to-left';

/**
 * Detect optimal mirror direction based on step content density.
 *
 * Smart detection: mirrors FROM the busier half TO the emptier half.
 * This prevents data loss when users have content in only one half.
 *
 * @param steps Boolean array indicating active steps
 * @param stepCount Number of steps to consider
 * @returns Direction to mirror: 'left-to-right' or 'right-to-left'
 */
export function detectMirrorDirection(steps: boolean[], stepCount: number): MirrorDirection {
  if (stepCount <= 2) return 'left-to-right'; // Default for short patterns

  const midpoint = Math.floor(stepCount / 2);

  // Count active steps in each half
  let firstHalfCount = 0;
  let secondHalfCount = 0;

  for (let i = 0; i < midpoint; i++) {
    if (steps[i]) firstHalfCount++;
  }
  for (let i = midpoint; i < stepCount; i++) {
    if (steps[i]) secondHalfCount++;
  }

  // Mirror FROM the busier half TO the emptier half
  // If equal, default to left-to-right (original behavior)
  return secondHalfCount > firstHalfCount ? 'right-to-left' : 'left-to-right';
}

/**
 * Mirror pattern: Create palindrome structure
 *
 * With smart detection (no direction specified):
 * - Analyzes which half has more content
 * - Mirrors FROM the busier half TO the emptier half
 * - Prevents data loss when content is in second half
 *
 * With explicit direction:
 * - 'left-to-right': First half → Second half (ABCD → ABBA)
 * - 'right-to-left': Second half → First half (DCBA → ABBA)
 *
 * Examples:
 * - [T,T,F,F,F,F,F,F] + left-to-right → [T,T,F,F,F,F,T,T]
 * - [F,F,F,F,F,F,T,T] + right-to-left → [T,T,F,F,F,F,T,T]
 * - [F,F,F,F,T,T,T,T] + auto → detects right-to-left → [T,T,T,T,T,T,T,T]
 *
 * @param arr Array to mirror (boolean[] or ParameterLock[])
 * @param stepCount Number of steps to consider
 * @param direction Optional direction; if omitted, uses smart detection for boolean arrays
 */
export function mirrorPattern<T>(
  arr: T[],
  stepCount: number,
  direction?: MirrorDirection
): T[] {
  if (stepCount <= 2) return [...arr]; // Return copy, too short to mirror

  const result = [...arr];
  const midpoint = Math.floor(stepCount / 2);

  // Use provided direction, or detect from array if it's boolean[]
  const effectiveDirection = direction ?? (
    Array.isArray(arr) && typeof arr[0] === 'boolean'
      ? detectMirrorDirection(arr as unknown as boolean[], stepCount)
      : 'left-to-right'
  );

  if (effectiveDirection === 'left-to-right') {
    // Copy first half to second half in reverse
    for (let i = 0; i < midpoint; i++) {
      result[stepCount - 1 - i] = result[i];
    }
  } else {
    // Copy second half to first half in reverse
    for (let i = 0; i < midpoint; i++) {
      result[i] = result[stepCount - 1 - i];
    }
  }

  return result;
}

/**
 * Bjorklund's algorithm for Euclidean rhythms
 * Distributes N hits across M steps as evenly as possible.
 *
 * Common patterns:
 * - E(3, 8) = Cuban tresillo: [X][ ][ ][X][ ][ ][X][ ]
 * - E(5, 8) = Cuban cinquillo: [X][ ][X][X][ ][X][X][ ]
 * - E(5, 16) = Bossa nova feel
 *
 * @param steps Total number of steps
 * @param hits Number of active steps to distribute
 * @returns Boolean array with hits distributed evenly
 */
export function euclidean(steps: number, hits: number): boolean[] {
  // Edge cases
  if (hits <= 0) return Array(steps).fill(false);
  if (hits >= steps) return Array(steps).fill(true);

  // Bjorklund's algorithm implementation
  // Build the pattern using the Euclidean algorithm for rhythm
  const pattern: boolean[] = [];

  // Start with groups: 'hits' groups of [true] and 'steps-hits' groups of [false]
  let groups: boolean[][] = [];
  for (let i = 0; i < hits; i++) {
    groups.push([true]);
  }
  for (let i = 0; i < steps - hits; i++) {
    groups.push([false]);
  }

  // Recursively distribute until we have one or two distinct group types
  while (true) {
    const firstGroup = groups[0];
    const lastGroupStart = groups.findIndex(
      (g, i) => i > 0 && !arraysEqual(g, firstGroup)
    );

    if (lastGroupStart === -1 || lastGroupStart === groups.length - 1) {
      break;
    }

    // How many groups are different from the first?
    const numTail = groups.length - lastGroupStart;
    const numHead = lastGroupStart;
    const toMerge = Math.min(numHead, numTail);

    if (toMerge === 0) break;

    // Merge tail groups into head groups
    const newGroups: boolean[][] = [];
    for (let i = 0; i < toMerge; i++) {
      newGroups.push([...groups[i], ...groups[lastGroupStart + i]]);
    }
    // Add remaining head groups
    for (let i = toMerge; i < numHead; i++) {
      newGroups.push(groups[i]);
    }
    // Add remaining tail groups
    for (let i = lastGroupStart + toMerge; i < groups.length; i++) {
      newGroups.push(groups[i]);
    }

    groups = newGroups;
  }

  // Flatten groups into final pattern
  for (const group of groups) {
    pattern.push(...group);
  }

  return pattern;
}

/**
 * Apply Euclidean distribution to a track, preserving parameter locks
 * on steps that remain active.
 */
export function applyEuclidean(
  currentSteps: boolean[],
  currentLocks: (ParameterLock | null)[],
  stepCount: number,
  hits: number
): { steps: boolean[]; locks: (ParameterLock | null)[] } {
  const newPattern = euclidean(stepCount, hits);
  const newSteps = [...currentSteps];
  const newLocks = [...currentLocks];

  // Apply new pattern within stepCount
  for (let i = 0; i < stepCount; i++) {
    const wasActive = newSteps[i];
    const willBeActive = newPattern[i];
    newSteps[i] = willBeActive;

    // Clear lock if step becomes inactive
    if (wasActive && !willBeActive) {
      newLocks[i] = null;
    }
  }

  return { steps: newSteps, locks: newLocks };
}

