  private handleSoloTrack = createTrackMutationHandler<
    { trackId: string; soloed: boolean },
    ServerMessage
  >({
    getTrackId: (msg) => msg.trackId,
    mutate: (track, msg) => { track.soloed = msg.soloed; },
