  /**
   * Change instrument (issue #63).
   *
   * Runs the same shared operation the browser reducer and MCP run, so all
   * three transports validate the instrument against the canonical catalog and
   * apply the identical engine-state policy. Unlike the other track handlers
   * this one cannot use createTrackMutationHandler: the shared operation is
   * pure, so the handler assigns the returned state the way handleMcpEdit does.
   *
   * A rejected request (unknown instrument or unknown track) is dropped without
   * mutating or broadcasting, matching every other track mutation handler. The
   * picker only ever offers catalog entries, so reaching this branch means a
   * stale or hostile client, and answering it with an `error` frame would raise
   * a banner in the sender's browser for a message a person never sent.
   */
  private async handleSetTrackInstrument(
    _ws: WebSocket,
    player: PlayerInfo,
    msg: {
      type: 'set_track_instrument' | 'set_track_sample';
      trackId: string;
      sampleId: string;
      name?: string;
      seq?: number;
    }
  ): Promise<void> {
    if (!this.state) return;

    const result = setTrackInstrument(this.state, msg);
    if (!result.ok) {
      console.warn(
        `[WS] session=${this.sessionId} player=${player.id} `
        + `Rejected set_track_instrument (${result.error.code}): ${result.error.message}`
      );
      return;
    }
    if (result.changed) {
      this.state = result.state;
      this.validateAndRepairState('handleSetTrackInstrument');
      await this.persistToDoStorage();
    }

    // Always answer with the rollout-compatible envelope, even when a direct
    // client used the new request type. One such request is broadcast to every
    // tab, including older tabs whose exhaustive switch rejects the new event.
    this.broadcast({
      type: 'track_sample_set',
      trackId: msg.trackId,
      sampleId: msg.sampleId,
      name: result.track.name,
      playerId: player.id,
    }, undefined, msg.seq);
  }

  /** Rolling-deploy alias; the caller-supplied name is never trusted. */
  private async handleSetTrackSample(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'set_track_sample'; trackId: string; sampleId: string; name: string; seq?: number }
  ): Promise<void> {
    await this.handleSetTrackInstrument(ws, player, msg);
  }

  private handleSetTrackVolume = createTrackMutationHandler<
    { trackId: string; volume: number },
    ServerMessage
  >({
    getTrackId: (msg) => msg.trackId,
    // Reject non-finite input before clamping — clamp() is Math.max/Math.min,
    // which passes NaN straight through. See GlobalMutationConfig.validate.
    validate: (msg) =>
      isValidNumber(msg.volume)
        ? { ...msg, volume: clamp(msg.volume, MIN_VOLUME, MAX_VOLUME) }
        : null,
    mutate: (track, msg) => { track.volume = msg.volume; },
    toBroadcast: (msg, playerId) => ({
      type: 'track_volume_set',
      trackId: msg.trackId,
      volume: msg.volume,
      playerId,
    }),
  });

  private handleSetTrackTranspose = createTrackMutationHandler<
    { trackId: string; transpose: number },
    ServerMessage
  >({
    getTrackId: (msg) => msg.trackId,
    // Math.round(NaN) is NaN, so rounding does not rescue a non-numeric input.
    validate: (msg) =>
      isValidNumber(msg.transpose)
        ? {
            ...msg,
            transpose: Math.round(clamp(msg.transpose, MIN_TRANSPOSE, MAX_TRANSPOSE)),
          }
        : null,
    mutate: (track, msg) => { track.transpose = msg.transpose; },
    toBroadcast: (msg, playerId) => ({
      type: 'track_transpose_set',
      trackId: msg.trackId,
      transpose: msg.transpose,
      playerId,
    }),
  });

  // Phase 31D: Per-track swing handler
  private handleSetTrackSwing = createTrackMutationHandler<
    { trackId: string; swing: number },
    ServerMessage
  >({
    getTrackId: (msg) => msg.trackId,
    // Same guard as volume and transpose: clamp() is Math.max/Math.min, which
    // passes a non-numeric value through as NaN. Per-track swing was missed
    // when those two were fixed.
    validate: (msg) =>
      isValidNumber(msg.swing)
        ? { ...msg, swing: clamp(msg.swing, MIN_SWING, MAX_SWING) }
        : null,
    mutate: (track, msg) => { track.swing = msg.swing; },
    toBroadcast: (msg, playerId) => ({
      type: 'track_swing_set',
      trackId: msg.trackId,
      swing: msg.swing,
      playerId,
    }),
  });

  private async handleSetTrackStepCount(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'set_track_step_count'; trackId: string; stepCount: number; seq?: number }
  ): Promise<void> {
    if (!this.state) return;

    const track = this.state.tracks.find(t => t.id === msg.trackId);
    if (!track) return;

    // Validate step count (Phase 29F: added odd counts for polyrhythm support)
    // Uses VALID_STEP_COUNTS_SET from shared/sync-types.ts (single source of truth)
    if (!VALID_STEP_COUNTS_SET.has(msg.stepCount as ValidStepCount)) {
      console.warn(`[WS] Invalid stepCount ${msg.stepCount} from ${player.id}`);
      return;
    }

    track.stepCount = msg.stepCount as ValidStepCount;
    // Arrays stay at MAX_STEPS (128) length - stepCount indicates active steps only
    // Invariant: track.steps.length === MAX_STEPS (see worker/invariants.ts)
    // This preserves user data when reducing stepCount (non-destructive editing)

    // Phase 27: Persist to DO storage immediately (hybrid persistence)
    await this.persistToDoStorage();

    // Phase 26: Pass clientSeq for mutation delivery confirmation
    this.broadcast({
      type: 'track_step_count_set',
      trackId: msg.trackId,
      stepCount: msg.stepCount,
      playerId: player.id,
    }, undefined, msg.seq);

    // Phase 27: KV is written on disconnect, not per-mutation (hybrid persistence)
  }

  /**
   * Phase 25: Handle effects state change
   * Syncs audio effects (reverb, delay, chorus, distortion) across all clients
   */
  private async handleSetEffects(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'set_effects'; effects: EffectsState; seq?: number }
  ): Promise<void> {
    if (!this.state) return;

    // Validate every numeric field, not just the four `wet` ones.
    //
    // The previous guard checked reverb.wet, delay.wet, chorus.wet and
    // distortion.wet, and left decay, feedback, frequency, depth and amount to
    // reach clamp() unchecked. clamp() is Math.max/Math.min, so a string or
    // object arrives as NaN, and the NaN was stored in session state and
    // broadcast to every collaborator. `typeof x === 'number'` is also not
    // enough on its own — JSON.parse turns 1e999 into Infinity — so this uses
    // the same isValidNumber guard as tempo, swing, volume and transpose.
    const numericEffectFields: Array<[string, unknown]> = msg.effects
      ? [
          ['reverb.decay', msg.effects.reverb?.decay],
          ['reverb.wet', msg.effects.reverb?.wet],
          ['delay.feedback', msg.effects.delay?.feedback],
          ['delay.wet', msg.effects.delay?.wet],
          ['chorus.frequency', msg.effects.chorus?.frequency],
          ['chorus.depth', msg.effects.chorus?.depth],
          ['chorus.wet', msg.effects.chorus?.wet],
          ['distortion.amount', msg.effects.distortion?.amount],
          ['distortion.wet', msg.effects.distortion?.wet],
        ]
      : [];

    const invalidField = numericEffectFields.find(([, value]) => !isValidNumber(value));
    if (!msg.effects || invalidField) {
      console.warn(
        `[WS] Invalid effects state from ${player.id}` +
        (invalidField ? `: ${invalidField[0]} is not a finite number` : '')
      );
      return;
    }

    // Clamp all values to valid ranges (using imported clamp from invariants)

    // Validate delay time or use default (VALID_DELAY_TIMES imported from invariants)
    const delayTime = VALID_DELAY_TIMES.has(msg.effects.delay.time)
      ? msg.effects.delay.time
      : '8n';

    const validatedEffects: EffectsState = {
      bypass: msg.effects.bypass === true,  // Default to false if not boolean true
      reverb: {
        decay: clamp(msg.effects.reverb.decay, 0.1, 10),
        wet: clamp(msg.effects.reverb.wet, 0, 1),
      },
      delay: {
        time: delayTime,
        feedback: clamp(msg.effects.delay.feedback, 0, 0.95),
        wet: clamp(msg.effects.delay.wet, 0, 1),
      },
      chorus: {
        frequency: clamp(msg.effects.chorus.frequency, 0.1, 10),
        depth: clamp(msg.effects.chorus.depth, 0, 1),
        wet: clamp(msg.effects.chorus.wet, 0, 1),
      },
      distortion: {
        amount: clamp(msg.effects.distortion.amount, 0, 1),
        wet: clamp(msg.effects.distortion.wet, 0, 1),
      },
    };

    this.state.effects = validatedEffects;

    // Phase 27: Persist to DO storage immediately (hybrid persistence)
    await this.persistToDoStorage();

    // Phase 26: Pass clientSeq for mutation delivery confirmation
    this.broadcast({
      type: 'effects_changed',
      effects: validatedEffects,
      playerId: player.id,
    }, undefined, msg.seq);

    // Phase 27: KV is written on disconnect, not per-mutation (hybrid persistence)
  }

  /**
   * Phase 29E: Handle scale state changes (Key Assistant)
   * Updates root, scaleId, and locked state for the session
   */
  private async handleSetScale(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'set_scale'; scale: ScaleState; seq?: number }
  ): Promise<void> {
    if (!this.state) return;

    // Validate scale object has required fields
    if (!msg.scale ||
        typeof msg.scale.root !== 'string' ||
        typeof msg.scale.scaleId !== 'string' ||
        typeof msg.scale.locked !== 'boolean') {
      console.warn(`[WS] Invalid scale state from ${player.id}`);
      return;
    }

    // Validate root note (C, C#, D, D#, E, F, F#, G, G#, A, A#, B)
    const validRoots = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    if (!validRoots.includes(msg.scale.root)) {
      console.warn(`[WS] Invalid scale root "${msg.scale.root}" from ${player.id}`);
      return;
    }

    const validatedScale: ScaleState = {
      root: msg.scale.root,
      scaleId: msg.scale.scaleId,
      locked: msg.scale.locked,
    };

    this.state.scale = validatedScale;

    // Phase 27: Persist to DO storage immediately (hybrid persistence)
    await this.persistToDoStorage();

    // Phase 26: Pass clientSeq for mutation delivery confirmation
    this.broadcast({
      type: 'scale_changed',
      scale: validatedScale,
      playerId: player.id,
    }, undefined, msg.seq);

    // Phase 27: KV is written on disconnect, not per-mutation (hybrid persistence)
  }

