  private handlePlay(ws: WebSocket, player: PlayerInfo): void {
    // Phase 22: Track per-player playback state
    this.playingPlayers.add(player.id);

    // Observability 2.0: Track play count and start time
    const obs = this.playerObservability.get(ws);
    if (obs) {
      obs.playCount++;
      obs.lastPlayStartTime = Date.now();
    }

    this.broadcast({
      type: 'playback_started',
      playerId: player.id,
      startTime: Date.now(),
      tempo: this.state?.tempo ?? 120,
    });
  }

  private handleStop(ws: WebSocket, player: PlayerInfo): void {
    // Phase 22: Track per-player playback state
    this.playingPlayers.delete(player.id);

    // Observability 2.0: Track total play time
    const obs = this.playerObservability.get(ws);
    if (obs && obs.lastPlayStartTime !== null) {
      obs.totalPlayTime_ms += Date.now() - obs.lastPlayStartTime;
      obs.lastPlayStartTime = null;
    }

    this.broadcast({
      type: 'playback_stopped',
      playerId: player.id,
    });
  }

  private handleStateHash(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'state_hash'; hash: string }
  ): void {
    if (!this.state) return;

    // Hash only comparable fields (exclude version, which client doesn't track)
    // Use canonicalizeForHash to normalize state before hashing for consistent
    // comparison between client and server (handles optional fields and array lengths)
    const comparableState = {
      tracks: this.state.tracks,
      tempo: this.state.tempo,
      swing: this.state.swing,
    };
    const canonicalState = canonicalizeForHash(comparableState);
    const serverHash = hashState(canonicalState);

    if (msg.hash !== serverHash) {
      // Track hash mismatches for observability
      const obs = this.playerObservability.get(ws);
      if (obs) {
        obs.hashMismatchCount++;
      }
      // Send mismatch notification to the client
      const response: ServerMessage = {
        type: 'state_mismatch',
        serverHash,
      };
      ws.send(JSON.stringify(response));
    } else {
      // Send match confirmation so client can reset consecutive mismatch counter
      const response: ServerMessage = {
        type: 'state_hash_match',
      };
      ws.send(JSON.stringify(response));
    }
  }

  /**
   * Handle request_snapshot - client requests full state (e.g., after mismatch)
   */
  private handleRequestSnapshot(ws: WebSocket, player: PlayerInfo): void {
    // Observability 2.0: Track sync request
    const obs = this.playerObservability.get(ws);
    if (obs) {
      obs.syncRequestCount++;
      // Track error if state is not loaded (shouldn't happen but possible)
      if (!this.state) {
        obs.syncErrorCount++;
      }
    }
    this.sendSnapshotToClient(ws, player, 'recovery');
  }

  /**
   * Phase 26 BUG-02: Send snapshot to a specific client
   * Unified helper for initial connect, recovery requests, and proactive catch-up
   */
  private sendSnapshotToClient(ws: WebSocket, player: PlayerInfo, _reason: 'recovery' | 'proactive' = 'recovery'): void {
    if (!this.state) return;

    // Track snapshots sent for observability (excluding initial connect)
    const obs = this.playerObservability.get(ws);
    if (obs) {
      obs.snapshotsSentCount++;
    }

    const players = Array.from(this.players.values());
    // Phase 21.5: Include timestamp for staleness checking
    // Phase 22: Include playingPlayerIds for presence indicators
    const response: ServerMessage = {
      type: 'snapshot',
      state: this.state,
      players,
      playerId: player.id,
      immutable: this.immutable,  // Phase 21: Include immutable flag
      snapshotTimestamp: Date.now(),  // Phase 21.5: For client staleness check
      serverSeq: this.serverSeq,  // Phase 26: For selective mutation clearing
      playingPlayerIds: Array.from(this.playingPlayers),  // Phase 22: Who's playing
    };
    ws.send(JSON.stringify(response));
  }

  private handleClockSyncRequest(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'clock_sync_request'; clientTime: number }
  ): void {
    const response: ServerMessage = {
      type: 'clock_sync_response',
      clientTime: msg.clientTime,
      serverTime: Date.now(),
    };
    ws.send(JSON.stringify(response));
  }

  /**
   * Phase 11: Handle cursor movement from a player
   * Broadcasts to all other players (not the sender)
   */
  private handleCursorMove(
    ws: WebSocket,
    player: PlayerInfo,
    msg: { type: 'cursor_move'; position: CursorPosition }
  ): void {
    // Validate and sanitize cursor position to prevent malicious clients
    // from sending extreme values that could cause issues on other clients
    const validatedPosition = validateCursorPosition(msg.position);
    if (!validatedPosition) {
      // Invalid position - silently ignore (don't log, too noisy)
      return;
    }

    // Broadcast to all other players with sanitized position
    this.broadcast({
      type: 'cursor_moved',
      playerId: player.id,
      position: validatedPosition,
      color: player.color,
      name: player.name,
    }, ws); // Exclude sender
  }

  // ==================== Utilities ====================

  /**
   * Ghost Avatar Fix: Prune stale connections that haven't sent messages
   * within the threshold (2 minutes). Rate-limited to once per minute.
   *
   * Called at the start of webSocketMessage() to clean up zombie connections
   * triggered by activity from other players.
   */
  private pruneStaleConnections(): void {
    const now = Date.now();

    // Rate limit: only check every PRUNE_CHECK_INTERVAL_MS (1 minute)
    if (now - this.lastPruneTime < PRUNE_CHECK_INTERVAL_MS) return;
    this.lastPruneTime = now;

    const staleConnections: WebSocket[] = [];

    for (const [ws, player] of this.players.entries()) {
      const timeSinceLastMessage = now - player.lastMessageAt;
      if (timeSinceLastMessage > STALE_CONNECTION_THRESHOLD_MS) {
        staleConnections.push(ws);
        console.log(`[PRUNE] Closing stale connection: player=${player.id}, silent for ${Math.round(timeSinceLastMessage / 1000)}s`);
      }
    }

    for (const ws of staleConnections) {
      ws.close(1000, 'Connection stale');
    }
  }

  /**
   * Phase 27: Persist state to DO storage immediately (hybrid persistence).
   * This ensures durability before broadcasting to clients.
   * Called by all mutation handlers after applying the mutation.
   */
  public async persistToDoStorage(): Promise<void> {
    if (!this.state) return;

    // Use 'state' key for consistency with existing code
    await this.ctx.storage.put('state', this.state);
    // Mark that KV needs to be flushed when last client disconnects
    this.pendingKVSave = true;
  }

  /**
   * Broadcast a message to all connected players
   * Phase 13B: Add sequence numbers for message ordering
   * Phase 26: Only add sequence numbers to state-mutating broadcasts
   * @param message - The message to broadcast
   * @param exclude - Optional WebSocket to exclude (usually the sender)
   * @param clientSeq - Optional client sequence number for request-response correlation
   */
  public broadcast(message: ServerMessage, exclude?: WebSocket, clientSeq?: number): void {
    // Phase 26: Only add sequence numbers to state-mutating broadcasts
    // Non-mutating messages (cursor_moved, player_joined, etc.) don't need
    // sequence numbers because missing them doesn't cause state drift
    const isMutating = isStateMutatingBroadcast(message.type);

    let messageToSend: ServerMessage;
    if (isMutating) {
      // Phase 13B: Add server sequence number to state-mutating broadcasts
      const newSeq = ++this.serverSeq;
      messageToSend = {
        ...message,
        seq: newSeq,
        ...(clientSeq !== undefined && { clientSeq }),
      };

      // Persist serverSeq periodically (every 100 messages) to survive hibernation/eviction
      if (newSeq % 100 === 0) {
        this.ctx.storage.put('serverSeq', newSeq).catch(e => {
          console.error('[DO] Error persisting serverSeq:', e);
        });
      }
    } else {
      // Non-mutating broadcasts don't get sequence numbers
      messageToSend = message;
    }

    const data = JSON.stringify(messageToSend);
    for (const [ws] of this.players) {
      if (ws === exclude) continue;
      try {
        ws.send(data);
      } catch (e) {
        console.error(`[WS] session=${this.sessionId} Error sending message:`, e);
      }
    }
  }

  /**
   * Save current state to KV and persist serverSeq to DO storage
   */
  private async saveToKV(): Promise<void> {
    if (!this.state || !this.sessionId) return;

    try {
      // Save session state to KV
      await updateSession(this.env, this.sessionId, this.state);
      // Persist serverSeq to DO storage to survive hibernation/eviction
      await this.ctx.storage.put('serverSeq', this.serverSeq);
    } catch (e) {
      console.error(`[KV] Error saving session ${this.sessionId}:`, e);
    }
  }

  /**
   * Merge a whole-state replacement over the currently loaded state.
   *
   * `effects`, `scale`, and `loopRegion` are optional in SessionState and are
   * only ever set over the WebSocket protocol, so REST clients that replace
   * state do not send them. `saveSessionNow` in the browser is exactly such a
   * client: it PUTs `{ tracks, tempo, swing, version }`. Assigning that body
   * directly would silently discard collaborative state the session already
   * has. A replacement that does carry one of these fields still wins.
   */
  private mergeStateReplacement(replacement: SessionState): SessionState {
    const previous = this.state;
    if (!previous) return replacement;

    return {
      ...replacement,
      effects: replacement.effects ?? previous.effects,
      scale: replacement.scale ?? previous.scale,
      loopRegion: replacement.loopRegion !== undefined
        ? replacement.loopRegion
        : previous.loopRegion,
    };
  }

  /**
   * Validate state invariants after mutation
   * Logs violations and optionally auto-repairs
   */
  private validateAndRepairState(context: string): void {
    if (!this.state || !this.sessionId) return;

    const result = validateStateInvariants(this.state);

    if (!result.valid) {
      // Log the violation for monitoring
      logInvariantStatus(this.state, this.sessionId, context);

      // Auto-repair if possible
      const { repairedState, repairs } = repairStateInvariants(this.state);
      if (repairs.length > 0) {
        console.warn(`[INVARIANT] Auto-repaired state for session=${this.sessionId}`, { repairs });
        this.state = repairedState;
      }
    }
  }

  /**
   * Handle debug HTTP request
   */
  private async handleDebugRequest(url: URL): Promise<Response> {
    // Extract session ID from URL and load state if not already loaded
    const pathParts = url.pathname.split('/');
    const sessionIdIndex = pathParts.indexOf('sessions') + 1;
    const sessionId = pathParts[sessionIdIndex] || this.sessionId;

    // Use ensureStateLoaded to safely load state with blockConcurrencyWhile
    if (!this.stateLoaded && sessionId) {
      await this.ensureStateLoaded(sessionId);
    }

    // Check invariants for the debug response
    const invariants = this.state
      ? validateStateInvariants(this.state)
      : { valid: true, violations: [], warnings: [] };

    const debug = {
      sessionId: this.sessionId,
      connectedPlayers: this.players.size,
      players: Array.from(this.players.values()),
      // Phase 22: Per-player playback tracking
      playingPlayerIds: Array.from(this.playingPlayers),
      playingCount: this.playingPlayers.size,
      trackCount: this.state?.tracks.length ?? 0,
      tempo: this.state?.tempo ?? 0,
      swing: this.state?.swing ?? 0,
      pendingKVSave: this.pendingKVSave,
      invariants: {
        valid: invariants.valid,
        violations: invariants.violations,
        warnings: invariants.warnings,
      },
    };

    return new Response(JSON.stringify(debug, null, 2), {
      headers: { 'Content-Type': 'application/json' },
    });
  }
}

/**
 * State hashing utilities for consistency verification
 *
 * Used by debug endpoints and the sync system to verify client/server state matches.
 *
 * Note: HTTP and WebSocket logging has been replaced by Observability 2.0 wide events.
 * See observability.ts for the new event-based logging system.
 */

import { DEFAULT_STEP_COUNT } from '../shared/constants';

// =============================================================================
// State Hashing for Consistency Verification (Phase 7)
// =============================================================================

// Minimal track type for hash input
interface TrackForHash {
  id: string;
  name: string;
  sampleId: string;
  steps: boolean[];
  parameterLocks: (unknown | null)[];
  volume: number;
  muted: boolean;
  soloed?: boolean;
  transpose: number;
  stepCount?: number;
  swing?: number;  // Phase 31D: Per-track swing (0-100)
}

interface StateForHash {
  tracks: TrackForHash[];
  tempo: number;
  swing: number;
  version?: number;
  effects?: unknown;
}

interface CanonicalTrack {
  id: string;
  name: string;
  sampleId: string;
  steps: boolean[];
  parameterLocks: (unknown | null)[];
  volume: number;
  // NOTE: muted and soloed are EXCLUDED from hash
  // They are local-only state ("My Ears, My Control" philosophy)
  transpose: number;
  stepCount: number;
  swing: number;  // Phase 31D: Per-track swing, defaults to 0
}

interface CanonicalState {
  tracks: CanonicalTrack[];
  tempo: number;
  swing: number;
}

/**
 * Normalize an array to exactly the target length.
 * - Truncates if longer than target
 * - Pads with defaultValue if shorter than target
 */
function normalizeArray<T>(arr: T[], targetLength: number, defaultValue: T): T[] {
  if (arr.length === targetLength) {
    return arr;
  }
  if (arr.length > targetLength) {
    return arr.slice(0, targetLength);
  }
  // Pad with default values
  const padding = new Array(targetLength - arr.length).fill(defaultValue);
  return [...arr, ...padding];
}

/**
 * Canonicalize a single track for consistent hashing.
 *
 * NOTE: muted and soloed are EXCLUDED from the canonical track.
 * These are local-only state per the "My Ears, My Control" philosophy.
 * Each user controls their own mix, so these values don't need to match
 * across clients for the session to be "in sync".
 */
function canonicalizeTrack(track: TrackForHash): CanonicalTrack {
  // Normalize optional fields to explicit defaults
  const stepCount = track.stepCount ?? DEFAULT_STEP_COUNT;
  const swing = track.swing ?? 0;  // Phase 31D: Default to 0 (uses global swing)

  // Normalize arrays to exactly stepCount length
  const steps = normalizeArray(track.steps, stepCount, false);
  const parameterLocks = normalizeArray(track.parameterLocks, stepCount, null);

  return {
    id: track.id,
    name: track.name,
    sampleId: track.sampleId,
    steps,
    parameterLocks,
    volume: track.volume,
    // muted: EXCLUDED - local-only
    // soloed: EXCLUDED - local-only
    transpose: track.transpose,
    stepCount,
    swing,  // Phase 31D: Per-track swing
  };
}

/**
 * Canonicalize session state for consistent hashing.
 *
 * This ensures that client and server produce identical hashes by:
 * 1. Setting explicit defaults for optional fields (stepCount)
 * 2. Normalizing array lengths to stepCount
 * 3. Excluding non-essential fields (version, effects)
 * 4. Excluding local-only fields (muted, soloed) per "My Ears, My Control"
 */
export function canonicalizeForHash(state: StateForHash): CanonicalState {
  return {
    tracks: state.tracks.map(canonicalizeTrack),
    tempo: state.tempo,
    swing: state.swing,
  };
}

/**
 * Compute a hash of the session state for consistency checks.
 * Uses a simple string hash since crypto.subtle is async and we need sync for tests.
 *
 * Note: In Cloudflare Workers, we could use crypto.subtle.digest, but this
 * simpler hash works well for detecting state divergence.
 */
export function hashState(state: unknown): string {
  const str = JSON.stringify(state);
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  // Convert to hex and pad
  return (hash >>> 0).toString(16).padStart(8, '0');
}

import { VALID_SAMPLE_IDS, getInstrumentName } from '../shared/instrument-catalog';
import { DEFAULT_STEP_COUNT, MAX_STEPS, MAX_TRACKS, MAX_TEMPO, MIN_TEMPO } from '../shared/constants';
import type { Session, SessionState, SessionTrack } from '../shared/state';
import { createDefaultTrack } from '../shared/state-mutations';
import { setTrackInstrument } from '../shared/track-instrument';
import { MAX_TRACK_NAME_LENGTH, sanitizeTrackName } from '../shared/validation';

export const MCP_ACTOR_ID = 'mcp';

export const MCP_SAMPLE_IDS = [...VALID_SAMPLE_IDS].sort();

/**
 * Caller-chosen track IDs deliberately exclude ":".
 *
 * The browser client builds its supersession keys as `${trackId}:${step}` for
 * step events and bare `trackId` for track events (see recordSupersession in
 * src/sync/multiplayer.ts). A track ID of "foo:3" would therefore produce the
 * same key as step 3 of track "foo", and an agent adding that track could make
 * a browser discard a collaborator's pending step edit. Browser-generated IDs
 * are `track-${Date.now()}`, so only MCP callers could reach the collision.
 */
export const TRACK_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

export type McpSessionEdit =
  | {
      operation: 'add_track';
      track_id: string;
      sample_id: string;
      name?: string;
    }
  | {
      operation: 'set_track_instrument';
      track_id: string;
      sample_id: string;
    }
  | {
      operation: 'set_steps';
      track_id: string;
      changes: Array<{ step: number; value: boolean }>;
    }
  | {
      operation: 'set_tempo';
      tempo: number;
    };

export type McpEditEvent =
  | { type: 'track_added'; track: SessionTrack }
  | { type: 'track_instrument_set'; trackId: string; sampleId: string; name: string }
  | { type: 'step_toggled'; trackId: string; step: number; value: boolean }
  | { type: 'tempo_changed'; tempo: number };

export interface CompactMcpTrack {
  track_id: string;
  name: string;
  sample_id: string;
  step_count: number;
  active_steps: number[];
}

export interface CompactMcpSession {
  session_id: string;
  immutable: boolean;
  tempo: number;
  tracks: CompactMcpTrack[];
}

export class McpSessionEditError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number
  ) {
    super(message);
    this.name = 'McpSessionEditError';
  }
}

export function compactMcpSession(session: Pick<Session, 'id' | 'immutable' | 'state'>): CompactMcpSession {
  return {
    session_id: session.id,
    immutable: session.immutable,
    tempo: session.state.tempo,
    tracks: session.state.tracks.map((track) => {
      const stepCount = track.stepCount ?? DEFAULT_STEP_COUNT;
      return {
        track_id: track.id,
        name: track.name,
        sample_id: track.sampleId,
        step_count: stepCount,
        active_steps: track.steps
          .slice(0, stepCount)
          .flatMap((active, step) => active ? [step] : []),
      };
    }),
  };
}

function assertValidTrackId(trackId: string): void {
  if (!TRACK_ID_PATTERN.test(trackId)) {
    throw new McpSessionEditError(
      'track_id must be 1-64 characters and use only letters, numbers, ".", "_", or "-".',
      'INVALID_TRACK_ID',
      400
    );
  }
}

function assertUniqueValidChanges(changes: Array<{ step: number; value: boolean }>): void {
  if (changes.length === 0 || changes.length > MAX_STEPS) {
    throw new McpSessionEditError(
      `changes must contain between 1 and ${MAX_STEPS} step assignments.`,
      'INVALID_STEPS',
      400
    );
  }

  const seen = new Set<number>();
  for (const change of changes) {
    if (!Number.isInteger(change.step) || change.step < 0 || change.step >= MAX_STEPS) {
      throw new McpSessionEditError(
        `step must be an integer from 0 to ${MAX_STEPS - 1}.`,
        'INVALID_STEP',
        400
      );
    }
    if (seen.has(change.step)) {
      throw new McpSessionEditError(
        `step ${change.step} appears more than once.`,
        'DUPLICATE_STEP',
        400
      );
    }
    seen.add(change.step);
  }
}

/**
 * Applies the complete MCP v1 edit surface without replacing a session or track.
 * The returned events use Keyboardia's existing browser collaboration messages.
 */
export function applyMcpSessionEdit(
  state: SessionState,
  edit: McpSessionEdit
): { state: SessionState; events: McpEditEvent[]; changed: boolean } {
  if (edit.operation === 'set_tempo') {
    if (!Number.isFinite(edit.tempo) || edit.tempo < MIN_TEMPO || edit.tempo > MAX_TEMPO) {
      throw new McpSessionEditError(
        `tempo must be between ${MIN_TEMPO} and ${MAX_TEMPO} BPM.`,
        'INVALID_TEMPO',
        400
      );
    }

    if (state.tempo === edit.tempo) {
      return { state, events: [], changed: false };
    }

    return {
      state: { ...state, tempo: edit.tempo },
      events: [{ type: 'tempo_changed', tempo: edit.tempo }],
      changed: true,
    };
  }

  assertValidTrackId(edit.track_id);

  if (edit.operation === 'add_track') {
    if (!VALID_SAMPLE_IDS.has(edit.sample_id)) {
      throw new McpSessionEditError(
        `Unknown sample_id: ${edit.sample_id}`,
        'INVALID_SAMPLE_ID',
        400
      );
    }

    const name = sanitizeTrackName(edit.name ?? getInstrumentName(edit.sample_id));
    if (!name) {
      throw new McpSessionEditError(
        `name must contain between 1 and ${MAX_TRACK_NAME_LENGTH} characters.`,
        'INVALID_TRACK_NAME',
        400
      );
    }

    const existing = state.tracks.find((track) => track.id === edit.track_id);
    if (existing) {
      if (existing.sampleId === edit.sample_id && existing.name === name) {
        return { state, events: [], changed: false };
      }
      throw new McpSessionEditError(
        `track_id ${edit.track_id} already belongs to a different track.`,
        'TRACK_ID_CONFLICT',
        409
      );
    }

    if (state.tracks.length >= MAX_TRACKS) {
      throw new McpSessionEditError(
        `A session can contain at most ${MAX_TRACKS} tracks.`,
        'TRACK_LIMIT_REACHED',
        409
      );
    }

    const track = createDefaultTrack(edit.track_id, edit.sample_id, name);
    return {
      state: { ...state, tracks: [...state.tracks, track] },
      events: [{ type: 'track_added', track }],
      changed: true,
    };
  }

  if (edit.operation === 'set_track_instrument') {
    // Change instrument (issue #63). The catalog check, the field preservation,
    // and the engine-state policy all live in the shared domain operation, so an
    // agent and a browser cannot reach different results. See
    // specs/CHANGE-INSTRUMENT.md.
    const result = setTrackInstrument(state, {
      trackId: edit.track_id,
      sampleId: edit.sample_id,
    });

    if (!result.ok) {
      throw new McpSessionEditError(
        result.error.message,
        result.error.code,
        result.error.code === 'TRACK_NOT_FOUND' ? 404 : 400
      );
    }

    if (!result.changed) {
      return { state, events: [], changed: false };
    }

    return {
      state: result.state,
      events: [{
        type: 'track_instrument_set',
        trackId: edit.track_id,
        sampleId: edit.sample_id,
        name: result.track.name,
      }],
      changed: true,
    };
  }

  assertUniqueValidChanges(edit.changes);
  const trackIndex = state.tracks.findIndex((track) => track.id === edit.track_id);
  if (trackIndex === -1) {
    throw new McpSessionEditError(
      `Track not found: ${edit.track_id}`,
      'TRACK_NOT_FOUND',
      404
    );
  }

  const track = state.tracks[trackIndex]!;
  const stepCount = track.stepCount ?? DEFAULT_STEP_COUNT;
  const outsideLoop = edit.changes.find((change) => change.step >= stepCount);
  if (outsideLoop) {
    throw new McpSessionEditError(
      `step ${outsideLoop.step} is outside this track's ${stepCount}-step loop.`,
      'STEP_OUTSIDE_LOOP',
      400
    );
  }

  const steps = [...track.steps];
  const events: McpEditEvent[] = [];
  for (const change of edit.changes) {
    if (steps[change.step] !== change.value) {
      steps[change.step] = change.value;
      events.push({
        type: 'step_toggled',
        trackId: edit.track_id,
        step: change.step,
        value: change.value,
      });
    }
  }

  if (events.length === 0) {
    return { state, events, changed: false };
  }

  const tracks = [...state.tracks];
  tracks[trackIndex] = { ...track, steps };
  return {
    state: { ...state, tracks },
    events,
    changed: true,
  };
}

/**
 * Pre-parse guards for the stateless MCP endpoint.
 *
 * These run in index.ts *before* `./mcp` is dynamically imported, so a
 * malformed request is rejected without evaluating the MCP SDK, zod, and the
 * schema validator — and without constructing an MCP server, fetching a
 * Durable Object, or reading KV.
 *
 * This module must never import `./mcp`, directly or transitively. Doing so
 * would pull the SDK into the main bundle and undo the dynamic import.
 */

import { MAX_MESSAGE_SIZE } from '../shared/constants';
import { isBodySizeValid } from './validation';

/** The only method the stateless endpoint serves. */
export const MCP_ALLOWED_METHODS = 'POST';

const PRODUCTION_ORIGINS = new Set([
  'https://keyboardia.dev',
  'https://www.keyboardia.dev',
]);
const STAGING_ORIGIN = 'https://staging.keyboardia.dev';

function isLoopbackHostname(hostname: string): boolean {
  return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]';
}

/**
 * Browser authorization is target-aware: development and staging origins must
 * never inherit write access to production. Staging additionally accepts the
 * production app as a higher-trust caller so the deployment smoke can exercise
 * a real cross-origin preflight. CLI clients normally omit Origin entirely.
 */
function isOriginAllowedForTarget(origin: URL, target: URL): boolean {
  const targetHostname = target.hostname.toLowerCase();
  if (targetHostname === 'keyboardia.dev' || targetHostname === 'www.keyboardia.dev') {
    return PRODUCTION_ORIGINS.has(origin.origin);
  }
  if (targetHostname === 'staging.keyboardia.dev') {
    return origin.origin === STAGING_ORIGIN || PRODUCTION_ORIGINS.has(origin.origin);
  }
  if (isLoopbackHostname(targetHostname)) {
    return isLoopbackHostname(origin.hostname.toLowerCase());
  }

  // Preview and other deployments do not trust sibling deployments: only the
  // exact HTTPS origin serving this endpoint may call it from a browser.
  return target.protocol === 'https:' && origin.origin === target.origin;
}

function parsedAllowedOrigin(request: Request): URL | null {
  const origin = request.headers.get('origin');
  if (!origin) return null;

  let parsed: URL;
  try {
    parsed = new URL(origin);
  } catch {
    return null;
  }

  if (
    (parsed.protocol !== 'https:' && parsed.protocol !== 'http:')
    || parsed.username !== ''
    || parsed.password !== ''
    || parsed.pathname !== '/'
    || parsed.search !== ''
    || parsed.hash !== ''
  ) {
    return null;
  }

  const hostname = parsed.hostname.toLowerCase();
  const isLocal = isLoopbackHostname(hostname);
  if (!isLocal && parsed.protocol !== 'https:') return null;
  if (!isLocal && parsed.port !== '') return null;
  if (!isOriginAllowedForTarget(parsed, new URL(request.url))) return null;

  return parsed;
}

/**
 * MCP Streamable HTTP requires a present Origin to be validated. Missing
 * Origin is valid because non-browser clients do not send one; a malformed,
 * opaque (`null`), or unapproved browser origin is rejected before parsing.
 */
export function validateMcpOrigin(request: Request): Response | undefined {
  const origin = request.headers.get('origin');
  if (!origin) return undefined;
  if (parsedAllowedOrigin(request)) return undefined;

  return new Response(JSON.stringify({
    jsonrpc: '2.0',
    error: {
      code: -32000,
      message: `Invalid Origin: ${origin}`,
    },
    id: null,
  }), {
    status: 403,
    headers: { 'Content-Type': 'application/json' },
  });
}

/** CORS metadata for a validated browser origin. */
export function mcpCorsHeaders(request: Request): Headers {
  const headers = new Headers({
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Accept, MCP-Protocol-Version, MCP-Method, MCP-Name',
    'Access-Control-Expose-Headers': 'MCP-Protocol-Version',
    'Access-Control-Max-Age': '86400',
    Vary: 'Origin',
  });
  const parsed = parsedAllowedOrigin(request);
  if (parsed) {
    headers.set('Access-Control-Allow-Origin', parsed.origin);
  }
  return headers;
}

/**
 * The stateless transport has no SSE stream to attach to and no MCP session to
 * terminate, so GET and DELETE are as unserviceable as PUT. The SDK answers
 * them with 405 too; rejecting here just does it before the SDK is loaded.
 */
function methodNotAllowed(): Response {
  return mcpGuardResponse(
    405,
    'METHOD_NOT_ALLOWED',
    'The Keyboardia MCP endpoint only accepts POST.',
    { Allow: MCP_ALLOWED_METHODS }
  );
}

function mcpGuardResponse(
  status: number,
  code: string,
  message: string,
  extraHeaders: Record<string, string> = {}
): Response {
  return new Response(JSON.stringify({ error: message, code }), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
  });
}

/**
 * `application/json; charset=utf-8` is the same media type as
 * `application/json`; `application/jsonl` is not. Compare only the type/subtype
 * so parameters are tolerated and near-misses are still rejected.
 */
export function isJsonContentType(contentType: string | null): boolean {
  if (!contentType) return false;
  const mediaType = contentType.split(';')[0]?.trim().toLowerCase();
  return mediaType === 'application/json';
}

/**
 * Retain at most the public limit and cancel as soon as the next stream chunk
 * would exceed it. This keeps an untrusted chunked request from forcing the
 * Worker to accumulate an arbitrarily large body before it can reject it.
 */
async function readBoundedBody(request: Request): Promise<ArrayBuffer | null> {
  if (!request.body) return new ArrayBuffer(0);

  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let totalBytes = 0;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      totalBytes += value.byteLength;
      if (totalBytes > MAX_MESSAGE_SIZE) {
        await reader.cancel('MCP request body exceeded the byte limit').catch(() => undefined);
        return null;
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const body = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body.buffer;
}

/**
 * Returns a rejection Response when the request cannot be served, or a rebuilt
 * Request whose body has been measured and is safe to hand to the MCP SDK.
 * CORS headers are applied by the caller, which decorates every /mcp response
 * the same way.
 */
export async function guardMcpRequest(request: Request): Promise<Response | Request> {
  const originRejection = validateMcpOrigin(request);
  if (originRejection) return originRejection;

  if (request.method !== 'POST') {
    return methodNotAllowed();
  }

  if (!isBodySizeValid(request.headers.get('content-length'))) {
    return mcpGuardResponse(
      413,
      'PAYLOAD_TOO_LARGE',
      `Request body exceeds the ${MAX_MESSAGE_SIZE}-byte limit.`
    );
  }

  if (!isJsonContentType(request.headers.get('content-type'))) {
    return mcpGuardResponse(
      415,
      'UNSUPPORTED_MEDIA_TYPE',
      'Content-Type must be application/json.'
    );
  }

  // Content-Length is only an early rejection hint. It can be absent or false,
  // so the bytes themselves are the authority. Rebuilding the request gives
  // the one-shot body back to the SDK without a second read from the network.
  const body = await readBoundedBody(request);
  if (!body) {
    return mcpGuardResponse(
      413,
      'PAYLOAD_TOO_LARGE',
      `Request body exceeds the ${MAX_MESSAGE_SIZE}-byte limit.`
    );
  }

  return new Request(request, { body });
}

/**
 * Transport-neutral logic behind the MCP session-lifecycle and export tools.
 *
 * Nothing here talks to KV, a Durable Object, or the MCP SDK, so each rule can
 * be tested directly. The adapter in mcp.ts supplies the storage.
 */

import {
  SYNTH_PROGRAM_MAP,
  encodeMidi,
  isDrumTrack,
} from '../shared/midi-core';
import { instrumentPresetId } from '../shared/instrument-classification';
import type { Session, SessionTrack } from '../shared/state';
import { hasActiveSteps } from '../shared/pattern-expansion';
import { McpSessionEditError } from './mcp-edits';

/**
 * How long a create key keeps resolving to the same session. An agent's retry
 * happens within seconds; a day is generous and bounds the stored keys.
 */
export const MCP_CREATE_IDEMPOTENCY_TTL_SECONDS = 24 * 60 * 60;

/**
 * The canonical URL an agent hands back to a person.
 *
 * Session UUIDs are the only access control Keyboardia has, so this is also why
 * `idempotency_key` is required to be a UUID rather than a caller-chosen label:
 * a memorable key like "house-beat" would let one agent's create silently
 * resolve to a different agent's session.
 */
export function sessionUrl(baseUrl: string, sessionId: string): string {
  return `${baseUrl.replace(/\/+$/, '')}/s/${sessionId}`;
}

export interface McpSessionRef {
  session_id: string;
  url: string;
  immutable: boolean;
  name: string | null;
  remixed_from: string | null;
}

export function sessionRef(baseUrl: string, session: Session): McpSessionRef {
  return {
    session_id: session.id,
    url: sessionUrl(baseUrl, session.id),
    immutable: session.immutable,
    name: session.name,
    remixed_from: session.remixedFrom,
  };
}

// ============================================================================
// MIDI export
// ============================================================================

export type McpMidiOmissionReason = 'muted' | 'not_soloed' | 'empty';

export interface McpMidiOmittedTrack {
  track_id: string;
  name: string;
  reason: McpMidiOmissionReason;
}

export interface McpMidiUnsupportedFeature {
  feature: string;
  detail: string;
  track_ids?: string[];
}

export interface McpMidiExport {
  session_id: string;
  filename: string;
  mime_type: 'audio/midi';
  encoding: 'base64';
  data: string;
  byte_length: number;
  tempo: number;
  swing: number;
  exported_track_ids: string[];
  omitted_tracks: McpMidiOmittedTrack[];
  /**
   * Session state the Standard MIDI File cannot carry. Reported rather than
   * approximated silently, so an agent can tell someone what will not survive
   * the trip into their DAW.
   */
  unsupported: McpMidiUnsupportedFeature[];
}

/**
 * Mirrors the track selection in exportToMidi(), which in turn mirrors the
 * audio scheduler: solo wins over mute, and silent tracks are skipped.
 */
function classifyTracks(tracks: SessionTrack[]): {
  exported: SessionTrack[];
  omitted: McpMidiOmittedTrack[];
} {
  const anySoloed = tracks.some((track) => track.soloed);
  const exported: SessionTrack[] = [];
  const omitted: McpMidiOmittedTrack[] = [];

  for (const track of tracks) {
    const shouldExport = anySoloed ? Boolean(track.soloed) : !track.muted;
    if (!shouldExport) {
      omitted.push({
        track_id: track.id,
        name: track.name,
        reason: anySoloed ? 'not_soloed' : 'muted',
      });
      continue;
    }
    if (!hasActiveSteps(track)) {
      omitted.push({ track_id: track.id, name: track.name, reason: 'empty' });
      continue;
    }
    exported.push(track);
  }

  return { exported, omitted };
}

/**
 * Everything the exporter drops or approximates, derived from the same session
 * the file was built from.
 */
export function describeUnsupportedMidiFeatures(
  session: Session,
  exportedTracks: SessionTrack[]
): McpMidiUnsupportedFeature[] {
  const unsupported: McpMidiUnsupportedFeature[] = [];

  const perTrackSwing = exportedTracks.filter((track) => (track.swing ?? 0) > 0);
  if (perTrackSwing.length > 0) {
    unsupported.push({
      feature: 'per_track_swing',
      detail: 'Only the session-wide swing is applied to note timing; per-track swing is not represented.',
      track_ids: perTrackSwing.map((track) => track.id),
    });
  }

  const mixedTracks = exportedTracks.filter((track) => track.volume !== 1);
  if (mixedTracks.length > 0) {
    unsupported.push({
      feature: 'track_volume',
      detail: 'Note velocity comes from per-step parameter locks only; track mix levels are not exported.',
      track_ids: mixedTracks.map((track) => track.id),
    });
  }

  const recordings = exportedTracks.filter((track) => track.sampleId.toLowerCase().startsWith('mic:'));
  if (recordings.length > 0) {
    unsupported.push({
      feature: 'custom_recordings',
      detail: 'A microphone recording has no General MIDI equivalent; these tracks are written as Middle C on the drum channel.',
      track_ids: recordings.map((track) => track.id),
    });
  }

  const unmappedInstruments = exportedTracks.filter((track) => {
    if (isDrumTrack(track)) return false;
    const presetId = instrumentPresetId(track.sampleId);
    return !(presetId in SYNTH_PROGRAM_MAP);
  });
  if (unmappedInstruments.length > 0) {
    unsupported.push({
      feature: 'instrument_program',
      detail: 'These instruments have no General MIDI program mapping and fall back to Acoustic Grand Piano.',
      track_ids: unmappedInstruments.map((track) => track.id),
    });
  }

  if (session.state.effects) {
    unsupported.push({
      feature: 'effects',
      detail: 'Reverb, delay, and filter settings are audio processing with no Standard MIDI File representation.',
    });
  }

  if (session.state.loopRegion) {
    unsupported.push({
      feature: 'loop_region',
      detail: 'The export always covers the full pattern; the editor loop region is not applied.',
    });
  }

  return unsupported;
}

/**
 * Workers have btoa but no Buffer. Chunked so a large file cannot blow the
 * argument limit on String.fromCharCode.
 */
export function toBase64(bytes: Uint8Array): string {
  const CHUNK = 0x8000;
  let binary = '';
  for (let offset = 0; offset < bytes.length; offset += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + CHUNK));
  }
  return btoa(binary);
}

/**
 * Runs Keyboardia's authoritative exporter over a session. The same
 * encodeMidi() the browser's Export MIDI button uses, so the bytes match for
 * identical state.
 */
export function exportSessionToMidi(session: Session): McpMidiExport {
  const { exported, omitted } = classifyTracks(session.state.tracks);

  if (exported.length === 0) {
    throw new McpSessionEditError(
      'This session has no audible notes to export.',
      'NOTHING_TO_EXPORT',
      409
    );
  }

  const { filename, midiData } = encodeMidi(
    {
      tracks: session.state.tracks,
      tempo: session.state.tempo,
      swing: session.state.swing,
    },
    { sessionName: session.name }
  );

  return {
    session_id: session.id,
    filename,
    mime_type: 'audio/midi',
    encoding: 'base64',
    data: toBase64(midiData),
    byte_length: midiData.byteLength,
    tempo: session.state.tempo,
    swing: session.state.swing,
    exported_track_ids: exported.map((track) => track.id),
    omitted_tracks: omitted,
    unsupported: describeUnsupportedMidiFeatures(session, exported),
  };
}

import { createMcpHandler, McpServer, type McpHttpHandler } from '@modelcontextprotocol/server';
import { z } from 'zod';
import { analyzeSession } from '../music/session-analysis';
import { MAX_STEPS, MAX_TEMPO, MIN_TEMPO } from '../shared/constants';
import type { Session } from '../shared/state';
import { PatternExpansionError } from '../shared/pattern-expansion';
import { MAX_SESSION_NAME_LENGTH, MAX_TRACK_NAME_LENGTH } from '../shared/validation';
import type { Env } from './types';
import {
  MCP_SAMPLE_IDS,
  McpSessionEditError,
  TRACK_ID_PATTERN,
  compactMcpSession,
  type CompactMcpSession,
  type McpSessionEdit,
} from './mcp-edits';
import {
  exportSessionToMidi,
  sessionRef,
  sessionUrl,
} from './mcp-lifecycle';
import { purgeOGCache } from './og-cache';
import { requestSessionAllocation, type SessionAllocationRequest } from './session-allocator';
import { getSession as getStoredSession } from './sessions';

interface DurableObjectStubLike {
  fetch(request: Request): Promise<Response>;
}

interface DurableObjectNamespaceLike {
  idFromName(name: string): unknown;
  get(id: unknown): DurableObjectStubLike;
}

export interface McpCreateSessionOptions {
  name?: string;
  tempo?: number;
  /** A caller-generated UUID. Replaying it returns the session it first made. */
  idempotencyKey: string;
}

export interface McpSessionAdapter {
  getSession(sessionId: string): Promise<Session>;
  editSession(sessionId: string, edit: McpSessionEdit): Promise<Session>;
  createSession(options: McpCreateSessionOptions): Promise<Session>;
  remixSession(sessionId: string): Promise<Session>;
  publishSession(sessionId: string): Promise<Session>;
}

/** Just the slice of ExecutionContext the publish path needs. */
export interface McpDeferralContext {
  waitUntil(promise: Promise<unknown>): void;
}

class McpSessionAdapterError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number
  ) {
    super(message);
    this.name = 'McpSessionAdapterError';
  }
}

function getDurableObjectStub(env: Env, sessionId: string): DurableObjectStubLike {
  const namespace = env.LIVE_SESSIONS as unknown as DurableObjectNamespaceLike;
  return namespace.get(namespace.idFromName(sessionId));
}

async function parseSessionResponse(response: Response): Promise<Session> {
  // A Durable Object that fails before its own handlers run can answer with a
  // non-JSON body. Turn that into a described adapter error rather than letting
  // a raw JSON parse message escape to the agent through the internal branch of
  // toolError().
  let body: Session & { error?: string; code?: string };
  try {
    body = await response.json() as Session & { error?: string; code?: string };
  } catch {
    throw new McpSessionAdapterError(
      `Keyboardia returned an unreadable response (HTTP ${response.status}).`,
      'SESSION_REQUEST_FAILED',
      response.status
    );
  }

  if (!response.ok) {
    throw new McpSessionAdapterError(
      body.error ?? `Keyboardia returned HTTP ${response.status}.`,
      body.code ?? 'SESSION_REQUEST_FAILED',
      response.status
    );
  }
  return body;
}

/**
 * Turns a failed create/remix/publish into the same described error shape the
 * edit path produces, so every tool reports failure identically.
 */
export function createDurableObjectSessionAdapter(
  env: Env,
  baseUrl: string,
  ctx?: McpDeferralContext,
  clientIp?: string | null
): McpSessionAdapter {
  async function getSession(sessionId: string): Promise<Session> {
    const stub = getDurableObjectStub(env, sessionId);
    const response = await stub.fetch(new Request(
      `https://keyboardia.internal/api/sessions/${encodeURIComponent(sessionId)}`,
      { method: 'GET' }
    ));
    return parseSessionResponse(response);
  }

  /**
   * Remix and publish both snapshot the source. The Durable Object holds edits
   * that have not reached KV yet, so it is asked first and KV is the fallback —
   * the same order the REST handlers in index.ts use.
   */
  async function readSourceSession(sessionId: string): Promise<Session> {
    try {
      return await getSession(sessionId);
    } catch (error) {
      if (error instanceof McpSessionAdapterError && error.status === 404) {
        throw error;
      }
      console.error('[MCP] DO read failed, falling back to KV:', error);
      const stored = await getStoredSession(env, sessionId, false);
      if (!stored) {
        throw new McpSessionAdapterError('Session not found.', 'SESSION_NOT_FOUND', 404);
      }
      return stored;
    }
  }

  async function allocate(request: SessionAllocationRequest): Promise<Session> {
    const result = await requestSessionAllocation(env, request);
    if (!result.success) {
      throw new McpSessionAdapterError(result.message, result.code, result.status);
    }
    return result.session;
  }

  return {
    getSession,

    async editSession(sessionId, edit) {
      const stub = getDurableObjectStub(env, sessionId);
      const response = await stub.fetch(new Request(
        `https://keyboardia.internal/api/sessions/${encodeURIComponent(sessionId)}/mcp-edit`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(edit),
        }
      ));
      return parseSessionResponse(response);
    },

    async createSession({ name, tempo, idempotencyKey }) {
      return allocate({
        operation: 'create',
        clientIp,
        idempotencyKey,
        options: {
          name: name ?? null,
          initialState: tempo === undefined ? undefined : { tempo },
        },
      });
    },

    async remixSession(sessionId) {
      const source = await readSourceSession(sessionId);
      return allocate({ operation: 'remix', clientIp, sourceId: sessionId, source });
    },

    async publishSession(sessionId) {
      const source = await readSourceSession(sessionId);
      if (source.immutable) {
        throw new McpSessionAdapterError(
          'This session is already published. Remix it first to get an editable copy.',
          'ALREADY_PUBLISHED',
          409
        );
      }

      const published = await allocate({
        operation: 'publish',
        clientIp,
        sourceId: sessionId,
        source,
      });

      // Same cache invalidation the REST publish route performs: the source's
      // cached preview predates publication, and the snapshot must not inherit
      // a stale entry. Never allowed to fail the publish it follows.
      const purge = Promise.all([
        purgeOGCache(sessionId, baseUrl),
        purgeOGCache(published.id, baseUrl),
      ])
        .then(() => undefined)
        .catch((error) => console.error('[OG] Cache purge failed:', error));
      ctx?.waitUntil(purge);

      return published;
    },
  };
}

const sampleIds = MCP_SAMPLE_IDS as [string, ...string[]];
const sessionIdSchema = z.uuid().describe(
  'The UUID after /s/ in a Keyboardia share URL. Pass only the UUID, not the full URL.'
);
const trackIdSchema = z.string()
  .regex(TRACK_ID_PATTERN)
  .describe(
    'For add_track, choose a stable unique ID and reuse it on retries. For set_steps or set_track_instrument, copy an existing track_id from get_session.'
  );
const sampleIdSchema = z.enum(sampleIds).describe(
  'The canonical Keyboardia instrument ID. Use one of the enumerated values exactly.'
);

const editSchema = z.object({
  session_id: sessionIdSchema,
  edit: z.discriminatedUnion('operation', [
    z.object({
      operation: z.literal('add_track'),
      track_id: trackIdSchema,
      sample_id: sampleIdSchema,
      name: z.string().trim().min(1).max(MAX_TRACK_NAME_LENGTH).optional()
        .describe('Optional display name. The instrument name is used when omitted.'),
    }).strict().describe(
      'Add one track. Retrying the same track_id and definition is a no-op; a conflicting reuse is rejected.'
    ),
    z.object({
      operation: z.literal('set_track_instrument'),
      track_id: trackIdSchema,
      sample_id: sampleIdSchema,
    }).strict().describe(
      'Replace only an existing track\'s sound source while preserving its name, pattern, mix, and timing.'
    ),
    z.object({
      operation: z.literal('set_steps'),
      track_id: trackIdSchema,
      changes: z.array(z.object({
        step: z.number().int().min(0).max(MAX_STEPS - 1)
          .describe('Zero-based step index. It must be within this track\'s current step_count.'),
        value: z.boolean().describe('true activates the step; false clears it.'),
      }).strict()).min(1).max(MAX_STEPS).superRefine((changes, context) => {
        const seen = new Set<number>();
        for (const change of changes) {
          if (seen.has(change.step)) {
            context.addIssue({
              code: 'custom',
              message: `step ${change.step} appears more than once`,
            });
          }
          seen.add(change.step);
        }
      }).describe('Assignments for named steps only. Every unmentioned step is preserved.'),
    }).strict().describe(
      'Change only the listed steps on an existing track. Read get_session first to obtain its track_id and step_count.'
    ),
    z.object({
      operation: z.literal('set_tempo'),
      tempo: z.number().min(MIN_TEMPO).max(MAX_TEMPO)
        .describe(`Session tempo in beats per minute (${MIN_TEMPO}-${MAX_TEMPO}).`),
    }).strict().describe('Set the session-wide tempo without changing any track.'),
  ]).describe('Exactly one narrow session edit.'),
}).strict().describe('The target session and one retry-safe edit to apply.');

const idempotencyKeySchema = z.uuid().describe(
  'A UUID you generate for this creation attempt. Reusing it returns the session the first attempt created instead of making another one.'
);

const sessionNameSchema = z.string().trim().min(1).max(MAX_SESSION_NAME_LENGTH)
  .describe('Optional display name for the new session.');

const tempoSchema = z.number().min(MIN_TEMPO).max(MAX_TEMPO)
  .describe(`Tempo in beats per minute (${MIN_TEMPO}-${MAX_TEMPO}).`);

function toolSuccess(session: CompactMcpSession) {
  return {
    content: [{ type: 'text' as const, text: JSON.stringify(session) }],
    structuredContent: { ...session },
  };
}

function toolPayload(payload: Record<string, unknown>) {
  return {
    content: [{ type: 'text' as const, text: JSON.stringify(payload) }],
    structuredContent: { ...payload },
  };
}

/**
 * Every session-lifecycle tool answers with the canonical /s/{session_id} URL
 * alongside the resulting music, so an agent always has something clickable to
 * hand back to a person.
 */
function lifecycleSuccess(
  baseUrl: string,
  session: Session,
  extra: Record<string, unknown> = {}
) {
  return toolPayload({
    ...sessionRef(baseUrl, session),
    ...compactMcpSession(session),
    ...extra,
  });
}

/**
 * Only Keyboardia's own described failures reach the agent. An unexpected error
 * is logged for operators and reported as a fixed message, because its text can
 * carry runtime, storage, or parser internals that an agent must not receive.
 */
function toolError(error: unknown) {
  if (error instanceof PatternExpansionError) {
    return {
      isError: true,
      content: [{
        type: 'text' as const,
        text: JSON.stringify({ error: error.message, code: error.code }),
      }],
    };
  }
  if (error instanceof McpSessionEditError || error instanceof McpSessionAdapterError) {
    return {
      isError: true,
      content: [{
        type: 'text' as const,
        text: JSON.stringify({ error: error.message, code: error.code }),
      }],
    };
  }

  console.error('[MCP] Unexpected tool failure:', error);
  return {
    isError: true,
    content: [{
      type: 'text' as const,
      text: JSON.stringify({
        error: 'Keyboardia could not complete this request.',
        code: 'INTERNAL_ERROR',
      }),
    }],
  };
}

function createKeyboardiaMcpServer(sessions: McpSessionAdapter, baseUrl: string): McpServer {
  const server = new McpServer({
    name: 'keyboardia',
    version: '1.0.0',
  }, {
    instructions: [
      'Read an existing session with get_session before editing it.',
      'Step indexes are zero-based; preserve every track and step the user did not ask to change.',
      'For add_track, choose a stable unique track_id and reuse it on retry. For set_steps and set_track_instrument, use a track_id returned by get_session.',
      'Only publish when the user explicitly asks. A session UUID grants the same access as its share URL, so do not expose it unnecessarily.',
    ].join(' '),
  });

  server.registerTool(
    'get_session',
    {
      title: 'Get Keyboardia session',
      description: 'Read the current tempo and compact track patterns from an existing Keyboardia session.',
      inputSchema: z.object({ session_id: sessionIdSchema }).strict(),
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ session_id }) => {
      try {
        return toolSuccess(compactMcpSession(await sessions.getSession(session_id)));
      } catch (error) {
        return toolError(error);
      }
    }
  );

  server.registerTool(
    'edit_session',
    {
      title: 'Edit Keyboardia session',
      description: [
        'Make one narrow, retry-safe edit to an existing collaborative session.',
        'Supported operations: add_track, set_track_instrument, set_steps, and set_tempo.',
        'set_steps changes only the named steps; it never replaces a track or session.',
        'set_track_instrument replaces only a track\'s sound source, keeping its'
        + ' pattern, mix, timing, and custom name.',
      ].join(' '),
      inputSchema: editSchema,
      annotations: {
        readOnlyHint: false,
        destructiveHint: true,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ session_id, edit }) => {
      try {
        return toolSuccess(compactMcpSession(await sessions.editSession(session_id, edit)));
      } catch (error) {
        return toolError(error);
      }
    }
  );

  server.registerTool(
    'create_session',
    {
      title: 'Create Keyboardia session',
      description: [
        'Create a new editable Keyboardia session with the normal defaults and return its shareable URL.',
        'The session starts with no tracks; use edit_session to add them.',
        'Pass the same idempotency_key when retrying so an uncertain attempt cannot leave duplicate sessions behind.',
      ].join(' '),
      inputSchema: z.object({
        idempotency_key: idempotencyKeySchema,
        name: sessionNameSchema.optional(),
        tempo: tempoSchema.optional()
          .describe('Starting tempo in BPM. Defaults to Keyboardia\'s own default.'),
      }).strict(),
      annotations: {
        readOnlyHint: false,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ idempotency_key, name, tempo }) => {
      try {
        const session = await sessions.createSession({ idempotencyKey: idempotency_key, name, tempo });
        return lifecycleSuccess(baseUrl, session);
      } catch (error) {
        return toolError(error);
      }
    }
  );

  server.registerTool(
    'remix_session',
    {
      title: 'Remix Keyboardia session',
      description: [
        'Copy an existing session — published or editable — into a new editable session that records the original as its source.',
        'The source is never modified, so this is how to continue from published work.',
      ].join(' '),
      inputSchema: z.object({ session_id: sessionIdSchema }).strict(),
      annotations: {
        readOnlyHint: false,
        destructiveHint: false,
        // Each call deliberately produces a separate remix.
        idempotentHint: false,
        openWorldHint: false,
      },
    },
    async ({ session_id }) => {
      try {
        const remix = await sessions.remixSession(session_id);
        return lifecycleSuccess(baseUrl, remix, {
          source_session_id: session_id,
          source_url: sessionUrl(baseUrl, session_id),
        });
      } catch (error) {
        return toolError(error);
      }
    }
  );

  server.registerTool(
    'publish_session',
    {
      title: 'Publish Keyboardia session',
      description: [
        'Freeze the current music into a new immutable session and return its URL.',
        'The source session stays editable at its own URL.',
        'Only call this when someone explicitly asks to publish; it is never a side effect of editing or exporting.',
      ].join(' '),
      inputSchema: z.object({ session_id: sessionIdSchema }).strict(),
      annotations: {
        readOnlyHint: false,
        destructiveHint: false,
        // Each call snapshots the music as it stands, producing a new session.
        idempotentHint: false,
        openWorldHint: false,
      },
    },
    async ({ session_id }) => {
      try {
        const published = await sessions.publishSession(session_id);
        return lifecycleSuccess(baseUrl, published, {
          source_session_id: session_id,
          source_url: sessionUrl(baseUrl, session_id),
        });
      } catch (error) {
        return toolError(error);
      }
    }
  );

  server.registerTool(
    'export_midi',
    {
      title: 'Export Keyboardia session as MIDI',
      description: [
        'Export the session as a base64-encoded Standard MIDI File, matching what Keyboardia\'s own Export MIDI produces for the same music.',
        'The session is not modified.',
        'The result lists any session features a MIDI file cannot carry rather than approximating them silently.',
      ].join(' '),
      inputSchema: z.object({ session_id: sessionIdSchema }).strict(),
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ session_id }) => {
      try {
        return toolPayload({
          ...exportSessionToMidi(await sessions.getSession(session_id)),
          url: sessionUrl(baseUrl, session_id),
        });
      } catch (error) {
        return toolError(error);
      }
    }
  );

  server.registerTool(
    'analyze_session',
    {
      title: 'Analyze Keyboardia session',
      description: [
        'Describe what is happening musically in a session — rhythm, pitch content, inferred key, and chords — without changing anything.',
        'Use this to explain music rather than to edit it.',
        'Results come from the same music-theory module the browser\'s Key Assistant and Chromatic Grid use, and report where the analysis is uncertain instead of guessing.',
      ].join(' '),
      inputSchema: z.object({ session_id: sessionIdSchema }).strict(),
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async ({ session_id }) => {
      try {
        const session = await sessions.getSession(session_id);
        return toolPayload({
          session_id: session.id,
          url: sessionUrl(baseUrl, session_id),
          immutable: session.immutable,
          ...analyzeSession(session.state),
        });
      } catch (error) {
        return toolError(error);
      }
    }
  );

  return server;
}

export function createKeyboardiaMcpHandler(
  sessions: McpSessionAdapter,
  baseUrl = 'https://keyboardia.dev'
): McpHttpHandler {
  return createMcpHandler(
    () => createKeyboardiaMcpServer(sessions, baseUrl),
    {
      legacy: 'stateless',
      onerror: (error) => console.error('[MCP]', error),
    }
  );
}

export function handleMcpRequest(
  request: Request,
  env: Env,
  ctx?: McpDeferralContext
): Promise<Response> {
  // Session URLs are built from the origin this request arrived on, so staging
  // and production each hand back their own links. Cloudflare only routes hosts
  // configured for this Worker, so the origin cannot be an arbitrary one.
  const baseUrl = new URL(request.url).origin;

  // The handler and its server factory are deliberately recreated for every
  // Worker request. Durable Objects hold music state; the MCP transport does not.
  return createKeyboardiaMcpHandler(
    createDurableObjectSessionAdapter(env, baseUrl, ctx, request.headers.get('CF-Connecting-IP')),
    baseUrl
  ).fetch(request);
}

/**
 * Observability 2.0: Wide Events Module
 *
 * Implements lifecycle-based wide events per the Observability 2.0 pattern.
 * See specs/OBSERVABILITY-2-0-IMPLEMENTATION.md for full specification.
 *
 * Two event types:
 * - http_request: One per HTTP request (errors embedded)
 * - ws_session: One per WebSocket connection (errors embedded)
 *
 * Events are emitted via console.log(JSON.stringify(...)) which sends them
 * to Cloudflare Workers Logs.
 */

import type { Env, VersionMetadata } from './types';

// =============================================================================
// Common Types
// =============================================================================

/**
 * Deployment information from CF_VERSION_METADATA binding
 */
export interface DeployInfo {
  versionId: string;
  versionTag?: string;
  deployedAt: string;
}

/**
 * Infrastructure information from request.cf
 */
export interface InfraInfo {
  colo: string;
  country: string;
}

/**
 * Service identity
 */
export interface ServiceInfo {
  name: string;
  environment: string;
}

/**
 * Error context (embedded in wide events when outcome === "error")
 */
export interface ErrorInfo {
  type: string;
  message: string;
  slug: string;
  expected: boolean;
  handler?: string;
  stack?: string;
}

/**
 * Warning for recovered errors and near-misses
 */
export interface Warning {
  type: string;
  message: string;
  occurredAt: string;
  recoveryAction: 'retry_succeeded' | 'fallback_used' | 'auto_repaired' | 'degraded_response';
  attemptNumber?: number;
  totalAttempts?: number;
  latency_ms?: number;
}

// =============================================================================
// Creator Identity (for isCreator detection)
// =============================================================================

/**
 * Creator identity for detecting if a WebSocket connection is the session creator.
 * Uses IP + User-Agent hash to identify users across page refreshes.
 *
 * Per spec: More reliable than playerId because:
 * 1. playerId is generated server-side on every WebSocket connection (ephemeral)
 * 2. Page refresh = new playerId, but IP + User-Agent remains stable
 * 3. Creator identity persists across page refreshes within same browser/network
 */
export interface CreatorIdentity {
  ip: string;           // CF-Connecting-IP header
  userAgentHash: string; // SHA-256 hash of User-Agent (first 16 chars)
}

/**
 * Hash User-Agent to avoid storing raw strings.
 * Uses SHA-256, returns first 16 hex chars (sufficient for identity).
 */
export async function hashUserAgent(userAgent: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(userAgent);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hash))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
    .slice(0, 16);
}

/**
 * Create a creator identity from a request.
 */
export async function createCreatorIdentity(request: Request): Promise<CreatorIdentity> {
  const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
  const userAgent = request.headers.get('User-Agent') || '';
  const userAgentHash = await hashUserAgent(userAgent);
  return { ip, userAgentHash };
}

/**
 * Compare two creator identities for equality.
 */
export function identitiesMatch(a: CreatorIdentity, b: CreatorIdentity): boolean {
  return a.ip === b.ip && a.userAgentHash === b.userAgentHash;
}

// =============================================================================
// Event Schemas
// =============================================================================

/**
 * HTTP Request wide event - emitted once per HTTP request
 */
export interface HttpRequestEvent {
  event: 'http_request';

  // Request identity
  requestId: string;
  method: string;
  path: string;
  deviceType: 'mobile' | 'desktop';

  // Timing
  timestamp: string;
  duration_ms: number;

  // Response
  status: number;
  responseSize?: number;

  // Context
  sessionId?: string;
  playerId?: string;
  isPublished?: boolean;
  sourceSessionId?: string;

  // Classification
  routePattern: string;
  action?: string;

  // Outcome (Boris Tane pattern)
  outcome: 'ok' | 'error';

  // Error context (only if outcome === "error")
  error?: ErrorInfo;

  // Performance
  kvReads?: number;
  kvWrites?: number;
  doRequests?: number;

  // Recovered errors
  warnings?: Warning[];

  // Deployment
  deploy: DeployInfo;

  // Infrastructure
  infra: InfraInfo;

  // Service identity
  service: ServiceInfo;
}

/**
 * WebSocket Session wide event - emitted once per WebSocket connection at disconnect
 */
export interface WsSessionEvent {
  event: 'ws_session';

  // Connection identity
  connectionId: string;
  sessionId: string;
  playerId: string;
  isCreator: boolean;
  isPublished: boolean;

  // Timing
  connectedAt: string;
  disconnectedAt: string;
  duration_ms: number;

  // Message stats
  messageCount: number;
  messagesByType: Record<string, number>;

  // Collaboration context
  peakConcurrentPlayers: number;
  playersSeenCount: number;

  // Playback
  playCount: number;
  totalPlayTime_ms: number;

  // Sync health
  syncRequestCount: number;
  syncErrorCount: number;

  // Additional behavioral metrics
  hashMismatchCount?: number;      // State sync mismatches detected
  snapshotsSentCount?: number;     // Manual snapshots sent (excluding initial)
  rejectedMutationCount?: number;  // Mutations rejected (published session)
  duplicateOpsHandled?: number;    // Duplicate track/delete operations

  // Outcome (Boris Tane pattern)
  outcome: 'ok' | 'error';
  disconnectReason: 'normal_close' | 'timeout' | 'replaced' | 'error';

  // Error context (only if outcome === "error")
  error?: ErrorInfo;

  // Recovered errors
  warnings?: Warning[];

  // Deployment
  deploy: DeployInfo;

  // Infrastructure
  infra: InfraInfo;

  // Service identity
  service: ServiceInfo;
}

// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Extract deployment info from environment
 */
export function getDeployInfo(env: Env): DeployInfo {
  const metadata: VersionMetadata | undefined = env.CF_VERSION_METADATA;
  return {
    versionId: metadata?.id ?? 'unknown',
    versionTag: metadata?.tag,
    deployedAt: metadata?.timestamp ?? new Date().toISOString(),
  };
}

/**
 * Extract infrastructure info from request.cf
 *
 * Note: request.cf is available in Cloudflare Workers and contains
 * geographic/network information about the request.
 */
export function getInfraInfo(request: Request): InfraInfo {
  // Type assertion needed because request.cf is not in the standard Request type
  const cf = (request as Request & { cf?: { colo?: string; country?: string } }).cf;
  return {
    colo: cf?.colo ?? 'unknown',
    country: cf?.country ?? 'unknown',
  };
}

/**
 * Extract service info from environment
 */
export function getServiceInfo(env: Env): ServiceInfo {
  return {
    name: env.SERVICE_NAME ?? 'keyboardia',
    environment: env.ENVIRONMENT ?? 'production',
  };
}

/**
 * Determine device type from User-Agent
 */
export function getDeviceType(userAgent: string | null): 'mobile' | 'desktop' {
  if (!userAgent) return 'desktop';

  const mobilePatterns = [
    /android/i,
    /webos/i,
    /iphone/i,
    /ipad/i,
    /ipod/i,
    /blackberry/i,
    /windows phone/i,
    /mobile/i,
  ];

  return mobilePatterns.some(pattern => pattern.test(userAgent)) ? 'mobile' : 'desktop';
}

// =============================================================================
// Warning Collection
// =============================================================================

const MAX_WARNINGS = 10;

/**
 * Collects warnings during request/connection lifecycle
 * Limited to MAX_WARNINGS to prevent unbounded growth
 */
export class WarningCollector {
  private warnings: Warning[] = [];

  add(warning: Omit<Warning, 'occurredAt'>): void {
    if (this.warnings.length < MAX_WARNINGS) {
      this.warnings.push({
        ...warning,
        occurredAt: new Date().toISOString(),
      });
    }
  }

  get(): Warning[] {
    return this.warnings;
  }

  hasWarnings(): boolean {
    return this.warnings.length > 0;
  }
}

// =============================================================================
// Error Classification
// =============================================================================

/**
 * Error slug mappings for common error types
 */
const ERROR_SLUGS: Record<number, { slug: string; expected: boolean }> = {
  400: { slug: 'bad-request', expected: true },
  401: { slug: 'unauthorized', expected: true },
  403: { slug: 'forbidden', expected: true },
  404: { slug: 'not-found', expected: true },
  405: { slug: 'method-not-allowed', expected: true },
  409: { slug: 'conflict', expected: true },
  413: { slug: 'payload-too-large', expected: true },
  429: { slug: 'rate-limited', expected: true },
  500: { slug: 'internal-error', expected: false },
  502: { slug: 'bad-gateway', expected: false },
  503: { slug: 'service-unavailable', expected: false },
  504: { slug: 'gateway-timeout', expected: false },
};

/**
 * Classify an error for the ErrorInfo structure
 */
export function classifyError(
  status: number,
  error: Error | string | null,
  handler?: string,
): ErrorInfo {
  const errorInfo = ERROR_SLUGS[status] ?? { slug: 'unknown-error', expected: false };
  const errorObj = typeof error === 'string' ? new Error(error) : error;

  let stack: string | undefined;
  if (errorObj?.stack && !errorInfo.expected) {
    // Truncate stack to 500 chars for unexpected errors only
    stack = errorObj.stack.slice(0, 500);
  }

  return {
    type: errorObj?.name ?? 'Error',
    message: errorObj?.message ?? 'Unknown error',
    slug: errorInfo.slug,
    expected: errorInfo.expected,
    handler,
    stack,
  };
}

/**
 * Create a custom error classification with specific slug
 */
export function classifyCustomError(
  type: string,
  message: string,
  slug: string,
  expected: boolean,
  handler?: string,
): ErrorInfo {
  return {
    type,
    message,
    slug,
    expected,
    handler,
  };
}

// =============================================================================
// Event Emission
// =============================================================================

type ObservabilityLogEnv = Pick<Env, 'OBSERVABILITY_LOGS_ENABLED'>;

function emitWideEvent(
  event: HttpRequestEvent | WsSessionEvent,
  env: ObservabilityLogEnv,
): void {
  // Cloudflare bindings are strings. Logging defaults on so production and
  // staging retain wide events unless a runner explicitly disables transport.
  if (env.OBSERVABILITY_LOGS_ENABLED === 'false') return;

  // Remove undefined fields to keep events clean.
  const cleanEvent = JSON.parse(JSON.stringify(event));
  console.log(JSON.stringify(cleanEvent));
}

/**
 * Emit an HTTP request wide event to Workers Logs
 */
export function emitHttpRequestEvent(
  event: HttpRequestEvent,
  env: ObservabilityLogEnv,
): void {
  emitWideEvent(event, env);
}

/**
 * Emit a WebSocket session wide event to Workers Logs
 */
export function emitWsSessionEvent(
  event: WsSessionEvent,
  env: ObservabilityLogEnv,
): void {
  emitWideEvent(event, env);
}

// =============================================================================
// WebSocket Close Code Mapping
// =============================================================================

/**
 * Map WebSocket close code to disconnect reason
 */
export function mapCloseCode(code: number): 'normal_close' | 'timeout' | 'replaced' | 'error' {
  // 1000 = normal close
  if (code === 1000) return 'normal_close';

  // 1001 = going away (navigation, tab close)
  if (code === 1001) return 'normal_close';

  // 4000+ = custom application codes
  if (code >= 4000 && code < 4100) return 'replaced';

  // 1006 = abnormal close (no close frame received) - likely timeout
  if (code === 1006) return 'timeout';

  // 1011 = unexpected condition
  // 1012 = service restart
  // 1013 = try again later
  // 1014 = bad gateway
  // 1015 = TLS handshake failure
  return 'error';
}

// =============================================================================
// Performance Metrics Tracking
// =============================================================================

/**
 * Tracks KV and DO operations for a single request
 */
export interface RequestMetrics {
  kvReads: number;
  kvWrites: number;
  doRequests: number;
}

/**
 * Create a new request metrics tracker
 */
export function createRequestMetrics(): RequestMetrics {
  return {
    kvReads: 0,
    kvWrites: 0,
    doRequests: 0,
  };
}

/**
 * Edge cache invalidation for generated social preview images.
 *
 * Split out of og-image.tsx deliberately: purging is a two-line cache delete,
 * while the renderer drags in React, Satori, and a Yoga WASM binary. Callers
 * that only need to invalidate — the publish paths — should not pay for or
 * depend on the renderer.
 */

/**
 * Purge the cached OG image for a session.
 * Call this when a session is published to ensure fresh image generation.
 *
 * @param sessionId - The session ID to purge
 * @param baseUrl - The base URL (e.g., https://keyboardia.dev)
 * @returns true if cache was deleted, false if not found
 */
export async function purgeOGCache(sessionId: string, baseUrl: string): Promise<boolean> {
  try {
    const cache = (caches as CacheStorage & { readonly default: Cache }).default;
    const cacheKey = new Request(`${baseUrl}/og/${sessionId}.png`);
    const deleted = await cache.delete(cacheKey);
    if (deleted) {
      console.log(`[OG] Cache purged for session ${sessionId}`);
    }
    return deleted;
  } catch (error) {
    console.error(`[OG] Failed to purge cache for ${sessionId}:`, error);
    return false;
  }
}

/**
 * Pure layout maths for the OG preview image.
 *
 * Split out of og-image.tsx because that module imports `workers-og`, which
 * loads a WASM binary at module scope and cannot be imported from a test. That
 * import barrier is why og-image.test.tsx previously carried its own copy of
 * condenseSteps, which had drifted from the original.
 */
export function condenseSteps(steps: boolean[], targetColumns: number): boolean[] {
  if (steps.length <= targetColumns) {
    return [...steps, ...Array(targetColumns - steps.length).fill(false)];
  }

  const ratio = steps.length / targetColumns;
  return Array.from({ length: targetColumns }, (_, i) => {
    const start = Math.floor(i * ratio);
    const end = Math.floor((i + 1) * ratio);
    return steps.slice(start, end).some(Boolean);
  });
}

/**
 * OG Image Generation Module
 *
 * Generates dynamic Open Graph images for social media sharing using Satori.
 * Images are 600x315 (1.91:1 ratio) for optimal platform compatibility.
 */

import React from 'react';
import { ImageResponse } from 'workers-og';
import type { Env } from './types';
import { condenseSteps } from './og-image-layout';
import type { Session } from '../shared/state';

const OG_WIDTH = 600;
const OG_HEIGHT = 315;

// Font cache to avoid repeated fetches within same worker instance
let fontCache: ArrayBuffer | null = null;

/**
 * Load Inter font for OG image rendering.
 * Font is bundled as a static asset in public/fonts/.
 * Cached in memory after first load.
 */
export async function loadFont(env: Env): Promise<ArrayBuffer> {
  if (fontCache) {
    return fontCache;
  }

  // Fetch from static assets (bundled with worker)
  const response = await env.ASSETS.fetch(
    new Request('https://keyboardia.dev/fonts/inter-regular.woff')
  );

  if (!response.ok) {
    throw new Error(`Failed to load font: ${response.status}`);
  }

  const font = await response.arrayBuffer();
  fontCache = font;
  return font;
}

// Brand colors
const COLORS = {
  background: '#0a0a0a',
  gridBackground: '#1a1a1a',
  activeStep: '#e85a30',
  inactiveStep: '#2a2a2a',
  text: '#ffffff',
  textMuted: '#888888',
  brand: '#ff6b35',
};

/**
 * OG image generation options
 */
interface OGImageProps {
  sessionName: string | null;
  tracks: Array<{ steps: boolean[] }>;
  tempo: number;
  trackCount: number;
}

/**
 * Generate the OG image as an ImageResponse
 * Uses workers-og package which wraps Satori + resvg-wasm
 */
export async function generateOGImage(props: OGImageProps, fontData?: ArrayBuffer): Promise<Response> {
  const { sessionName, tracks, tempo, trackCount } = props;

  // Condense tracks to 16 columns for display (max 4 tracks shown)
  const displayTracks = tracks.slice(0, 4).map(track =>
    condenseSteps(track.steps, 16)
  );

  // Pad to 4 tracks if fewer
  while (displayTracks.length < 4) {
    displayTracks.push(Array(16).fill(false));
  }

  // Build fonts array once
  const fonts = fontData ? [
    { name: 'Inter', data: fontData, weight: 400 as const, style: 'normal' as const },
    { name: 'Inter', data: fontData, weight: 600 as const, style: 'normal' as const },
    { name: 'Inter', data: fontData, weight: 700 as const, style: 'normal' as const },
  ] : undefined;

  // Helper to create ImageResponse - may need retry if WASM race condition occurs
  const createImageResponse = () => new ImageResponse(
    (
      <div
        style={{
          width: `${OG_WIDTH}px`,
          height: `${OG_HEIGHT}px`,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
          padding: '24px',
          backgroundColor: COLORS.background,
          fontFamily: 'Inter, system-ui, sans-serif',
        }}
      >
        {/* Step grid visualization */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: '4px',
            padding: '16px',
            backgroundColor: COLORS.gridBackground,
            borderRadius: '8px',
          }}
        >
          {displayTracks.map((steps, trackIndex) => (
            <div
              key={trackIndex}
              style={{
                display: 'flex',
                gap: '3px',
              }}
            >
              {steps.map((active, stepIndex) => (
                <div
                  key={stepIndex}
                  style={{
                    width: '30px',
                    height: '20px',
                    backgroundColor: active ? COLORS.activeStep : COLORS.inactiveStep,
                    borderRadius: '2px',
                  }}
                />
              ))}
            </div>
          ))}
        </div>

        {/* Footer with session info */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'flex-end',
          }}
        >
          {/* Session name and metadata */}
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            <div
              style={{
                display: 'flex',
                fontSize: '24px',
                fontWeight: 600,
                color: COLORS.text,
                marginBottom: '4px',
              }}
            >
              {sessionName || 'Untitled Session'}
            </div>
            <div
              style={{
                display: 'flex',
                fontSize: '12px',
                color: COLORS.textMuted,
              }}
            >
              {`${trackCount} tracks · ${tempo} BPM`}
            </div>
          </div>

          {/* Keyboardia branding */}
          <div
            style={{
              display: 'flex',
              fontSize: '16px',
              fontWeight: 700,
              color: COLORS.brand,
            }}
          >
            KEYBOARDIA
          </div>
        </div>
      </div>
    ),
    {
      width: OG_WIDTH,
      height: OG_HEIGHT,
      fonts,
    }
  );

  // Try to create the image, with retry for WASM initialization race condition
  // The "Already initialized" error occurs when concurrent requests both try to init WASM
  // On retry, WASM is already initialized so it succeeds
  try {
    return createImageResponse();
  } catch (error) {
    if (error instanceof Error && error.message.includes('Already initialized')) {
      // WASM was initialized by another concurrent request - retry should work
      console.log('[OG] WASM already initialized, retrying...');
      return createImageResponse();
    }
    throw error;
  }
}

// purgeOGCache lives in ./og-cache so callers that only invalidate the cache do
// not have to load the renderer. Re-exported here for existing importers.
export { purgeOGCache } from './og-cache';

/**
 * Handle OG image generation requests
 * Route: /og/:sessionId.png
 * Phase 34: Routes through DO for latest state (includes pending changes)
 */
export async function handleOGImageRequest(
  request: Request,
  env: Env,
  ctx: ExecutionContext,
  url: URL
): Promise<Response> {
  const sessionId = url.pathname.match(/^\/og\/([a-f0-9-]{36})\.png$/)?.[1];

  if (!sessionId) {
    return new Response('Not Found', { status: 404 });
  }

  // Check cache first
  const cacheKey = new Request(url.toString());
  const cache = (caches as CacheStorage & { readonly default: Cache }).default;
  const cachedResponse = await cache.match(cacheKey);

  if (cachedResponse) {
    return cachedResponse;
  }

  // Phase 34: Get session from DO (source of truth) instead of direct KV read
  // This ensures OG images show the latest state including pending changes
  let sessionData: Session | null = null;
  try {
    const doId = env.LIVE_SESSIONS.idFromName(sessionId);
    const stub = env.LIVE_SESSIONS.get(doId);
    const doResponse = await stub.fetch(new Request(
      new URL(`/api/sessions/${sessionId}`, request.url).toString(),
      { method: 'GET' }
    ));
    if (doResponse.ok) {
      sessionData = await doResponse.json() as Session;
    }
  } catch (error) {
    // Fall back to KV if DO fails (session might not exist or DO error)
    console.log(`[OG] DO fetch failed for ${sessionId}, falling back to KV:`, error);
    sessionData = await env.SESSIONS.get(`session:${sessionId}`, 'json') as Session | null;
  }

  if (!sessionData) {
    // Return default OG image for missing sessions
    return env.ASSETS.fetch(new Request(`${url.origin}/og-image.png`));
  }

  try {
    // Load font (cached in memory after first load)
    let fontData: ArrayBuffer | undefined;
    try {
      fontData = await loadFont(env);
      console.log('[OG] Font loaded successfully, size:', fontData.byteLength);
    } catch (fontError) {
      console.warn('[OG] Failed to load font, using fallback:', fontError);
      // Continue without custom font - workers-og will use system fonts
    }

    // Prepare image props
    const props = {
      sessionName: sessionData.name,
      tracks: sessionData.state?.tracks?.map(t => ({ steps: t.steps })) ?? [],
      tempo: sessionData.state?.tempo ?? 120,
      trackCount: sessionData.state?.tracks?.length ?? 0,
    };
    console.log('[OG] Generating image for session:', sessionData.name, 'tracks:', props.trackCount);

    // Generate image
    const response = await generateOGImage(props, fontData);
    console.log('[OG] Image generated successfully, status:', response.status);

    // Create response with caching headers
    const cacheTtl = sessionData.immutable ? 604800 : 3600; // 7 days vs 1 hour

    const headers = new Headers(response.headers);
    headers.set('Cache-Control', `public, max-age=${cacheTtl}`);

    const cachedResp = new Response(response.body, {
      status: response.status,
      headers,
    });

    // Store in cache asynchronously (don't block response)
    ctx.waitUntil(cache.put(cacheKey, cachedResp.clone()));

    return cachedResp;
  } catch (error) {
    // Log error for debugging with full details
    console.error('[OG] Image generation failed:', error);
    console.error('[OG] Error name:', (error as Error)?.name);
    console.error('[OG] Error message:', (error as Error)?.message);
    console.error('[OG] Error stack:', (error as Error)?.stack);

    // Return fallback static image on any error
    return env.ASSETS.fetch(new Request(`${url.origin}/og-image.png`));
  }
}

/**
 * Loose in-memory per-IP rate limiting for request classes that should shed
 * abusive traffic before expensive work begins.
 *
 * The map lives in the isolate, so limits reset when a Worker restarts and are
 * per-colo rather than global. That is accepted: this exists to keep one
 * visitor from burning compute or render budget, not to defeat a distributed
 * attack. Permanent session allocation uses the global SessionAllocator
 * Durable Object instead, where the write budget is serialized and persisted.
 *
 * @see specs/STATELESS-MCP.md - "Deferred hardening" for the remaining WAF
 *      and authenticated-identity layers.
 */

import type { Env } from './types';

const RATE_LIMIT_WINDOW_MS = 60 * 1000; // 1 minute window

/**
 * Per-minute, per-IP budgets. These are the *production* numbers.
 *
 * A load test that needs more raises the matching var in wrangler.jsonc; it
 * does not edit these. The session-create limit previously sat at 100 with a
 * "revert after testing" comment attached, which is how a temporary test value
 * became the shipped production limit for months.
 */
export const RATE_LIMIT_DEFAULTS = {
  // Each create is a KV write against a daily quota.
  sessionCreate: 10,
  // Covers every MCP exchange, including read-only tools and malformed calls.
  mcpRequest: 120,
  // Each miss renders an image; edge caching means the origin sees far fewer
  // requests than a crawler makes.
  ogImage: 100,
} as const;

export type RateLimitBucket = keyof typeof RATE_LIMIT_DEFAULTS;

const RATE_LIMIT_VARS: Record<RateLimitBucket, keyof Env> = {
  sessionCreate: 'SESSION_CREATE_RATE_LIMIT_PER_MINUTE',
  mcpRequest: 'MCP_RATE_LIMIT_PER_MINUTE',
  ogImage: 'OG_IMAGE_RATE_LIMIT_PER_MINUTE',
};

/**
 * An unset, empty, non-numeric, fractional, or non-positive override falls back
 * to the production default rather than silently disabling the limit.
 */
export function resolveRateLimit(env: Env, bucket: RateLimitBucket): number {
  const raw = env[RATE_LIMIT_VARS[bucket]];
  if (raw === undefined || raw === null || raw === '') {
    return RATE_LIMIT_DEFAULTS[bucket];
  }
  const configured = Number(raw);
  if (!Number.isInteger(configured) || configured < 1) {
    return RATE_LIMIT_DEFAULTS[bucket];
  }
  return configured;
}

interface RateLimitEntry {
  count: number;
  windowStart: number;
}

export interface RateLimitDecision {
  allowed: boolean;
  remaining: number;
  resetIn: number;
}

/**
 * Buckets are keyed separately per limit. Sharing one counter across endpoints
 * means a burst of OG image requests can exhaust an IP's session-create budget,
 * which is an unrelated denial of service against the same visitor.
 */
export function createRateLimitChecker(now: () => number = Date.now) {
  const entries = new Map<string, RateLimitEntry>();

  return (bucket: RateLimitBucket, ip: string, max: number): RateLimitDecision => {
    const timestamp = now();
    const key = `${bucket}:${ip}`;
    const entry = entries.get(key);

    // Clean up old entries periodically (simple garbage collection)
    if (entries.size > 10000) {
      for (const [mapKey, value] of entries.entries()) {
        if (timestamp - value.windowStart > RATE_LIMIT_WINDOW_MS) {
          entries.delete(mapKey);
        }
      }
    }

    if (!entry || timestamp - entry.windowStart > RATE_LIMIT_WINDOW_MS) {
      entries.set(key, { count: 1, windowStart: timestamp });
      return { allowed: true, remaining: max - 1, resetIn: RATE_LIMIT_WINDOW_MS };
    }

    if (entry.count >= max) {
      const resetIn = RATE_LIMIT_WINDOW_MS - (timestamp - entry.windowStart);
      return { allowed: false, remaining: 0, resetIn };
    }

    entry.count++;
    const resetIn = RATE_LIMIT_WINDOW_MS - (timestamp - entry.windowStart);
    return { allowed: true, remaining: max - entry.count, resetIn };
  };
}

const checkDefaultRateLimit = createRateLimitChecker();

export function checkRateLimit(bucket: RateLimitBucket, ip: string, max: number): RateLimitDecision {
  return checkDefaultRateLimit(bucket, ip, max);
}

/**
 * Route Pattern Matching for Observability
 *
 * Maps API paths to route patterns and actions for the http_request event.
 * Patterns use :param notation for dynamic segments.
 */

export interface RouteMatch {
  pattern: string;
  action?: string;
}

/**
 * Route definitions with their patterns and actions
 */
interface RouteDefinition {
  pathRegex: RegExp;
  pattern: string;
  getAction: (method: string) => string | undefined;
}

const ROUTE_DEFINITIONS: RouteDefinition[] = [
  // Session create
  {
    pathRegex: /^\/api\/sessions\/?$/,
    pattern: '/api/sessions',
    getAction: (method) => method === 'POST' ? 'create' : undefined,
  },

  // Session CRUD
  {
    pathRegex: /^\/api\/sessions\/([^/]+)\/?$/,
    pattern: '/api/sessions/:id',
    getAction: (method) => {
      switch (method) {
        case 'GET': return 'access';
        case 'PUT':
        case 'PATCH': return 'update';
        case 'DELETE': return 'delete';
        default: return undefined;
      }
    },
  },

  // Session remix
  {
    pathRegex: /^\/api\/sessions\/([^/]+)\/remix\/?$/,
    pattern: '/api/sessions/:id/remix',
    getAction: () => 'remix',
  },

  // Session publish
  {
    pathRegex: /^\/api\/sessions\/([^/]+)\/publish\/?$/,
    pattern: '/api/sessions/:id/publish',
    getAction: () => 'publish',
  },

  // Session WebSocket
  {
    pathRegex: /^\/api\/sessions\/([^/]+)\/ws\/?$/,
    pattern: '/api/sessions/:id/ws',
    getAction: () => 'websocket',
  },

  // Debug endpoints
  {
    pathRegex: /^\/api\/debug\/logs\/?$/,
    pattern: '/api/debug/logs',
    getAction: () => 'debug_logs',
  },
  {
    pathRegex: /^\/api\/debug\/logs\/session\/([^/]+)\/?$/,
    pattern: '/api/debug/logs/session/:id',
    getAction: () => 'debug_session_logs',
  },
  {
    pathRegex: /^\/api\/debug\/metrics\/?$/,
    pattern: '/api/debug/metrics',
    getAction: () => 'debug_metrics',
  },
  {
    pathRegex: /^\/api\/debug\/session\/([^/]+)\/?$/,
    pattern: '/api/debug/session/:id',
    getAction: () => 'debug_session',
  },
  {
    pathRegex: /^\/api\/debug\/session\/([^/]+)\/live\/?$/,
    pattern: '/api/debug/session/:id/live',
    getAction: () => 'debug_live',
  },

  // Health check
  {
    pathRegex: /^\/api\/health\/?$/,
    pattern: '/api/health',
    getAction: () => 'health',
  },

  // Samples endpoint
  {
    pathRegex: /^\/api\/samples\/([^/]+)\/?$/,
    pattern: '/api/samples/:id',
    getAction: (method) => method === 'GET' ? 'sample_access' : undefined,
  },
];

/**
 * Match a path and method to a route pattern and action
 */
export function matchRoute(path: string, method: string): RouteMatch {
  for (const route of ROUTE_DEFINITIONS) {
    if (route.pathRegex.test(path)) {
      return {
        pattern: route.pattern,
        action: route.getAction(method),
      };
    }
  }

  // Unknown route
  return {
    pattern: path, // Use actual path as pattern for unknown routes
    action: undefined,
  };
}

/**
 * Extract session ID from a path if present
 */
export function extractSessionId(path: string): string | undefined {
  // Match /api/sessions/:id and /api/sessions/:id/*
  const match = path.match(/^\/api\/sessions\/([^/]+)/);
  return match ? match[1] : undefined;
}

/** Whether a path belongs to the client-rendered session application. */
export function isSessionPagePath(path: string): boolean {
  return path.startsWith('/s/');
}

/**
 * The single write gate for every operation that allocates a permanent session.
 *
 * All callers address one named Durable Object, so allocation limits and MCP
 * create idempotency are serialized across Worker isolates and colos. For an
 * idempotent create, the UUID reservation is persisted before KV is touched;
 * concurrent calls and retries therefore converge on one session identity even
 * if the first KV write has an uncertain outcome.
 */

import type { Session } from '../shared/state';
import { MCP_CREATE_IDEMPOTENCY_TTL_SECONDS } from './mcp-lifecycle';
import { resolveRateLimit } from './rate-limit';
import {
  createSession,
  getSession,
  publishSessionFromState,
  remixSessionFromState,
  type CreateSessionOptions,
  type SessionResult,
} from './sessions';
import type { Env } from './types';

const ALLOCATOR_NAME = 'global-session-allocator';
const RATE_WINDOW_MS = 60_000;

interface DurableObjectStorageLike {
  get<T>(key: string): Promise<T | undefined>;
  put<T>(key: string, value: T): Promise<void>;
  delete(key: string): Promise<boolean>;
  list<T>(options: { prefix: string }): Promise<Map<string, T>>;
  getAlarm(): Promise<number | null>;
  setAlarm(scheduledTime: number | Date): Promise<void>;
}

interface DurableObjectStateLike {
  storage: DurableObjectStorageLike;
  blockConcurrencyWhile<T>(callback: () => Promise<T>): Promise<T>;
}

interface DurableObjectStubLike {
  fetch(request: Request): Promise<Response>;
}

interface DurableObjectNamespaceLike {
  idFromName(name: string): unknown;
  get(id: unknown): DurableObjectStubLike;
}

interface AllocationBase {
  clientIp?: string | null;
}

export type SessionAllocationRequest =
  | (AllocationBase & {
      operation: 'create';
      options: Omit<CreateSessionOptions, 'id'>;
      idempotencyKey?: string;
    })
  | (AllocationBase & {
      operation: 'remix';
      sourceId: string;
      source: Session;
    })
  | (AllocationBase & {
      operation: 'publish';
      sourceId: string;
      source: Session;
    });

export type SessionAllocationResponse =
  | { success: true; session: Session }
  | {
      success: false;
      code: 'RATE_LIMITED' | 'QUOTA_EXCEEDED' | 'SESSION_WRITE_FAILED' | 'ALREADY_PUBLISHED';
      status: number;
      message: string;
      retryAfter?: number;
    };

interface RateWindow {
  count: number;
  windowStart: number;
}

interface IdempotencyReservation {
  sessionId: string;
  expiresAt: number;
  options: Omit<CreateSessionOptions, 'id'>;
}

function publicWriteFailure<T>(result: Extract<SessionResult<T>, { success: false }>): SessionAllocationResponse {
  if (result.quotaExceeded) {
    return {
      success: false,
      code: 'QUOTA_EXCEEDED',
      status: 503,
      message: 'Keyboardia has reached its daily storage quota. Try again after it resets at midnight UTC.',
    };
  }
  return {
    success: false,
    code: 'SESSION_WRITE_FAILED',
    status: 500,
    message: 'Keyboardia could not save the session. Please try again.',
  };
}

export class SessionAllocatorDurableObject {
  constructor(
    private readonly state: DurableObjectStateLike,
    private readonly env: Env
  ) {}

  fetch(request: Request): Promise<Response> {
    return this.state.blockConcurrencyWhile(async () => {
      if (request.method !== 'POST') return new Response('Not found', { status: 404 });

      let allocation: SessionAllocationRequest;
      try {
        allocation = await request.json() as SessionAllocationRequest;
      } catch {
        return Response.json({
          success: false,
          code: 'SESSION_WRITE_FAILED',
          status: 500,
          message: 'Keyboardia could not save the session. Please try again.',
        } satisfies SessionAllocationResponse, { status: 500 });
      }

      const result = await this.allocate(allocation);
      return Response.json(result, { status: result.success ? 200 : result.status });
    });
  }

  /** Durable Object storage has no per-key TTL, so one alarm owns expiry. */
  alarm(): Promise<void> {
    return this.state.blockConcurrencyWhile(async () => {
      const now = Date.now();
      let nextExpiry: number | null = null;

      const rateWindows = await this.state.storage.list<RateWindow>({ prefix: 'rate:' });
      for (const [key, window] of rateWindows) {
        const expiresAt = window.windowStart + RATE_WINDOW_MS;
        if (expiresAt <= now) await this.state.storage.delete(key);
        else nextExpiry = nextExpiry === null ? expiresAt : Math.min(nextExpiry, expiresAt);
      }

      const reservations = await this.state.storage.list<IdempotencyReservation>({
        prefix: 'idempotency:create:',
      });
      for (const [key, reservation] of reservations) {
        if (reservation.expiresAt <= now) await this.state.storage.delete(key);
        else {
          nextExpiry = nextExpiry === null
            ? reservation.expiresAt
            : Math.min(nextExpiry, reservation.expiresAt);
        }
      }

      if (nextExpiry !== null) await this.state.storage.setAlarm(nextExpiry);
    });
  }

  private async scheduleCleanup(expiresAt: number): Promise<void> {
    const scheduled = await this.state.storage.getAlarm();
    if (scheduled === null || expiresAt < scheduled) {
      await this.state.storage.setAlarm(expiresAt);
    }
  }

  private async charge(clientIp?: string | null): Promise<SessionAllocationResponse | null> {
    if (!clientIp) return null;

    const now = Date.now();
    const key = `rate:${clientIp}`;
    const limit = resolveRateLimit(this.env, 'sessionCreate');
    const current = await this.state.storage.get<RateWindow>(key);

    if (!current || now - current.windowStart >= RATE_WINDOW_MS) {
      await this.state.storage.put(key, { count: 1, windowStart: now });
      await this.scheduleCleanup(now + RATE_WINDOW_MS);
      return null;
    }
    if (current.count >= limit) {
      return {
        success: false,
        code: 'RATE_LIMITED',
        status: 429,
        message: 'Too many sessions created. Please wait before creating another.',
        retryAfter: Math.max(1, Math.ceil((RATE_WINDOW_MS - (now - current.windowStart)) / 1000)),
      };
    }

    await this.state.storage.put(key, { ...current, count: current.count + 1 });
    await this.scheduleCleanup(current.windowStart + RATE_WINDOW_MS);
    return null;
  }

  private async writeCreated(options: CreateSessionOptions): Promise<SessionAllocationResponse> {
    const result = await createSession(this.env, options);
    if (!result.success) {
      console.error('[SessionAllocator] create failed:', result.error);
      return publicWriteFailure(result);
    }
    return { success: true, session: result.data };
  }

  private async createIdempotently(
    request: Extract<SessionAllocationRequest, { operation: 'create' }>
  ): Promise<SessionAllocationResponse> {
    const reservationKey = `idempotency:create:${request.idempotencyKey}`;
    const now = Date.now();
    let reservation = await this.state.storage.get<IdempotencyReservation>(reservationKey);

    if (reservation && reservation.expiresAt > now) {
      await this.scheduleCleanup(reservation.expiresAt);
      const existing = await getSession(this.env, reservation.sessionId, false);
      if (existing) return { success: true, session: existing };

      // The UUID was already committed as the outcome of this key. Retry the
      // same write with the original options; never mint a replacement UUID.
      return this.writeCreated({ ...reservation.options, id: reservation.sessionId });
    }

    if (reservation) await this.state.storage.delete(reservationKey);
    const limited = await this.charge(request.clientIp);
    if (limited) return limited;

    reservation = {
      sessionId: crypto.randomUUID(),
      expiresAt: now + MCP_CREATE_IDEMPOTENCY_TTL_SECONDS * 1000,
      options: request.options,
    };

    // Commit the identity before performing the non-transactional KV write.
    // If this fails, no session has been allocated and the caller gets a fixed
    // error. If KV fails later, a retry finds this reservation and reuses it.
    try {
      await this.state.storage.put(reservationKey, reservation);
      await this.scheduleCleanup(reservation.expiresAt);
    } catch (error) {
      console.error('[SessionAllocator] idempotency reservation failed:', error);
      return {
        success: false,
        code: 'SESSION_WRITE_FAILED',
        status: 500,
        message: 'Keyboardia could not save the session. Please try again.',
      };
    }

    return this.writeCreated({ ...reservation.options, id: reservation.sessionId });
  }

  private async allocate(request: SessionAllocationRequest): Promise<SessionAllocationResponse> {
    if (request.operation === 'create' && request.idempotencyKey) {
      return this.createIdempotently(request);
    }

    if (request.operation === 'publish' && request.source.immutable) {
      return {
        success: false,
        code: 'ALREADY_PUBLISHED',
        status: 409,
        message: 'Cannot publish from an already-published session. Remix it first to create an editable copy.',
      };
    }

    const limited = await this.charge(request.clientIp);
    if (limited) return limited;

    let result: SessionResult<Session>;
    if (request.operation === 'create') {
      result = await createSession(this.env, request.options);
    } else if (request.operation === 'remix') {
      result = await remixSessionFromState(this.env, request.sourceId, request.source);
    } else {
      result = await publishSessionFromState(this.env, request.sourceId, request.source);
    }

    if (!result.success) {
      console.error(`[SessionAllocator] ${request.operation} failed:`, result.error);
      return publicWriteFailure(result);
    }
    return { success: true, session: result.data };
  }
}

export async function requestSessionAllocation(
  env: Env,
  allocation: SessionAllocationRequest
): Promise<SessionAllocationResponse> {
  const namespace = env.SESSION_ALLOCATOR as unknown as DurableObjectNamespaceLike;
  const stub = namespace.get(namespace.idFromName(ALLOCATOR_NAME));
  let response: Response;
  try {
    response = await stub.fetch(new Request('https://keyboardia.internal/allocate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(allocation),
    }));
  } catch (error) {
    console.error('[SessionAllocator] request failed:', error);
    return {
      success: false,
      code: 'SESSION_WRITE_FAILED',
      status: 500,
      message: 'Keyboardia could not save the session. Please try again.',
    };
  }

  try {
    return await response.json() as SessionAllocationResponse;
  } catch (error) {
    console.error('[SessionAllocator] unreadable response:', error);
    return {
      success: false,
      code: 'SESSION_WRITE_FAILED',
      status: 500,
      message: 'Keyboardia could not save the session. Please try again.',
    };
  }
}

/**
 * Session CRUD operations using KV storage
 */

import type { Env, Session, SessionState } from './types';
import { createInitialSessionState } from '../shared/session-defaults';

// Sessions are permanent by default (no TTL)
const CURRENT_VERSION = 1;

/**
 * Result type for operations that can fail with quota errors
 */
export type SessionResult<T> =
  | { success: true; data: T }
  | { success: false; quotaExceeded: boolean; error: string };

/**
 * Check if an error is a KV quota limit error
 */
function isKVQuotaError(error: unknown): boolean {
  return error instanceof Error && error.message.includes('limit exceeded');
}

/**
 * Calculate seconds until midnight UTC (when quota resets)
 */
export function getSecondsUntilMidnightUTC(): number {
  const now = new Date();
  const midnight = new Date(now);
  midnight.setUTCHours(24, 0, 0, 0);
  return Math.ceil((midnight.getTime() - now.getTime()) / 1000);
}

/**
 * Generate a cryptographically secure UUID v4
 */
function generateSessionId(): string {
  return crypto.randomUUID();
}

/**
 * Options for creating a new session
 */
export interface CreateSessionOptions {
  /** Pre-reserved by the allocation Durable Object for idempotent creates. */
  id?: string;
  /** Initial session state (tracks, tempo, swing) */
  initialState?: Partial<SessionState>;
  /** Optional session name */
  name?: string | null;
}

/**
 * Create a new session
 */
export async function createSession(
  env: Env,
  options?: CreateSessionOptions
): Promise<SessionResult<Session>> {
  const id = options?.id ?? generateSessionId();
  const now = Date.now();


  const session: Session = {
    id,
    name: options?.name ?? null,
    createdAt: now,
    updatedAt: now,
    lastAccessedAt: now,
    remixedFrom: null,
    remixedFromName: null,
    remixCount: 0,
    immutable: false,
    state: createInitialSessionState(options?.initialState),
  };

  try {
    await env.SESSIONS.put(`session:${id}`, JSON.stringify(session));
    return { success: true, data: session };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      quotaExceeded: isKVQuotaError(error),
      error: message,
    };
  }
}

/**
 * Get a session by ID (also updates lastAccessedAt)
 */
export async function getSession(
  env: Env,
  id: string,
  updateAccess: boolean = true
): Promise<Session | null> {
  const data = await env.SESSIONS.get(`session:${id}`, 'json') as Session | null;
  if (!data) return null;

  // Backwards compatibility: add missing fields
  const session: Session = {
    ...data,
    name: data.name ?? null,
    lastAccessedAt: data.lastAccessedAt ?? data.updatedAt ?? data.createdAt,
    remixedFromName: data.remixedFromName ?? null,
    remixCount: data.remixCount ?? 0,
    immutable: data.immutable ?? false,
  };

  // Update lastAccessedAt on read (async, don't await)
  if (updateAccess) {
    const now = Date.now();
    session.lastAccessedAt = now;
    env.SESSIONS.put(`session:${id}`, JSON.stringify(session)).catch(() => {
      // Ignore errors on access time update
    });
  }

  return session;
}

/**
 * Update a session's state
 */
export async function updateSession(
  env: Env,
  id: string,
  state: SessionState
): Promise<SessionResult<Session> | null> {
  // Pass false to avoid race condition with async lastAccessedAt update
  const existing = await getSession(env, id, false);
  if (!existing) return null;

  const updated: Session = {
    ...existing,
    updatedAt: Date.now(),
    state: { ...state, version: CURRENT_VERSION },
  };

  try {
    await env.SESSIONS.put(`session:${id}`, JSON.stringify(updated));
    return { success: true, data: updated };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      quotaExceeded: isKVQuotaError(error),
      error: message,
    };
  }
}

/**
 * Phase 34: Remix a session from a pre-fetched state (DO-provided)
 *
 * This function creates a remix using state that was fetched from the DO,
 * ensuring we use the latest state (including pending changes not yet in KV).
 *
 * This fixes the architectural violation where remixSession() read directly
 * from KV, potentially getting stale data when DO had pending changes.
 */
export async function remixSessionFromState(
  env: Env,
  sourceId: string,
  source: Session
): Promise<SessionResult<Session>> {
  const id = generateSessionId();
  const now = Date.now();

  // Get a display name for the source session (use first track name or "Untitled")
  const sourceName = source.state.tracks.length > 0
    ? source.state.tracks[0].name
    : 'Untitled Session';

  const remixed: Session = {
    id,
    name: null,  // Start fresh, don't inherit source name
    createdAt: now,
    updatedAt: now,
    lastAccessedAt: now,
    remixedFrom: sourceId,
    remixedFromName: source.name ?? sourceName,
    remixCount: 0,
    immutable: false,  // Remixes are always editable
    state: { ...source.state },
  };

  // Increment remix count on source (async, don't block)
  // Note: We update KV directly here since this is metadata, not session state
  source.remixCount = (source.remixCount ?? 0) + 1;
  env.SESSIONS.put(`session:${sourceId}`, JSON.stringify(source)).catch(() => {
    // Ignore errors on remix count update
  });

  try {
    await env.SESSIONS.put(`session:${id}`, JSON.stringify(remixed));
    return { success: true, data: remixed };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      quotaExceeded: isKVQuotaError(error),
      error: message,
    };
  }
}

/**
 * Update a session's name
 */
export async function updateSessionName(
  env: Env,
  id: string,
  name: string | null
): Promise<SessionResult<Session> | null> {
  const existing = await getSession(env, id, false);
  if (!existing) return null;

  // Sanitize name: trim, limit length, allow null
  const sanitizedName = name
    ? name.trim().slice(0, 100) || null
    : null;

  const updated: Session = {
    ...existing,
    name: sanitizedName,
    updatedAt: Date.now(),
  };

  try {
    await env.SESSIONS.put(`session:${id}`, JSON.stringify(updated));
    return { success: true, data: updated };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      quotaExceeded: isKVQuotaError(error),
      error: message,
    };
  }
}

/**
 * Phase 34: Publish a session from a pre-fetched state (DO-provided)
 *
 * This function creates a published snapshot using state that was fetched from the DO,
 * ensuring we use the latest state (including pending changes not yet in KV).
 *
 * This fixes the architectural violation where publishSession() read directly
 * from KV, potentially getting stale data when DO had pending changes.
 */
export async function publishSessionFromState(
  env: Env,
  sourceId: string,
  source: Session
): Promise<SessionResult<Session>> {
  // Source already immutable? Can't publish from a published session
  // (User should remix first to get an editable copy)
  if (source.immutable) {
    return {
      success: false,
      quotaExceeded: false,
      error: 'Cannot publish from an already-published session. Remix it first to create an editable copy.',
    };
  }

  const id = generateSessionId();
  const now = Date.now();

  // Get a display name for the source session
  const sourceName = source.name ??
    (source.state.tracks.length > 0 ? source.state.tracks[0].name : 'Untitled Session');

  const published: Session = {
    id,
    name: source.name,  // Keep the name for published version
    createdAt: now,
    updatedAt: now,
    lastAccessedAt: now,
    remixedFrom: sourceId,
    remixedFromName: sourceName,
    remixCount: 0,
    immutable: true,  // KEY: This is a frozen snapshot
    state: { ...source.state },
  };

  try {
    await env.SESSIONS.put(`session:${id}`, JSON.stringify(published));
    return { success: true, data: published };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      quotaExceeded: isKVQuotaError(error),
      error: message,
    };
  }
}

/**
 * Social Media Preview Module
 *
 * Handles crawler detection and dynamic meta tag injection for social sharing.
 * Uses HTMLRewriter for streaming HTML transformation.
 */

/**
 * Session metadata for social previews
 */
export interface SessionMeta {
  id: string;
  name: string | null;
  trackCount: number;
  tempo: number;
}

/**
 * Escape HTML special characters to prevent XSS in meta tag content.
 * Session names are user-provided and could contain malicious characters.
 */
export function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * Generate JSON-LD structured data for Schema.org
 *
 * Uses MusicComposition rather than MusicRecording because:
 * - Sessions are interactive compositions, not fixed recordings
 * - Sessions loop infinitely (no duration)
 * - No actual audio file exists at the URL
 *
 * Keyboardia is listed as composer (Organization) until we have user accounts.
 */
function generateJsonLd(session: SessionMeta, url: string, baseUrl: string): string {
  // XSS prevention: escape session name for JSON context
  const safeName = session.name ? escapeHtml(session.name) : 'Untitled Session';
  const ogImage = `${baseUrl}/og/${session.id}.png`;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'MusicComposition',
    'name': safeName,
    'url': url,
    'image': ogImage,
    'composer': {
      '@type': 'Organization',
      'name': 'Keyboardia',
      'url': baseUrl,
      'logo': `${baseUrl}/icon-192.png`,
      'description': 'Collaborative step sequencer for creating beats together in real-time'
    }
  };

  return `<script type="application/ld+json">${JSON.stringify(jsonLd)}</script>`;
}

/**
 * Inject social media meta tags into HTML response using HTMLRewriter
 * @param response - The base HTML response to transform
 * @param session - Session metadata for the preview
 * @param baseUrl - The base URL of the current environment (e.g., https://staging.keyboardia.dev)
 */
export function injectSocialMeta(
  response: Response,
  session: SessionMeta,
  baseUrl: string
): Response {
  // XSS prevention: escape user-provided session name
  const safeName = session.name ? escapeHtml(session.name) : null;

  const title = safeName
    ? `${safeName} — Keyboardia`
    : 'Untitled Session — Keyboardia';

  const description = safeName
    ? `Listen to "${safeName}" on Keyboardia. A ${session.trackCount}-track beat at ${session.tempo} BPM. Create beats together in real-time.`
    : `Listen to this beat on Keyboardia. A ${session.trackCount}-track composition at ${session.tempo} BPM. Create beats together in real-time.`;

  const url = `${baseUrl}/s/${session.id}`;
  const ogImage = `${baseUrl}/og/${session.id}.png`;

  // Track if we've appended to head (to avoid duplicates)
  let headAppended = false;

  return new HTMLRewriter()
    .on('title', {
      element(el) {
        el.setInnerContent(title);
      }
    })
    .on('meta[name="title"]', {
      element(el) {
        el.setAttribute('content', title);
      }
    })
    .on('meta[name="description"]', {
      element(el) {
        el.setAttribute('content', description);
      }
    })
    .on('meta[property="og:title"]', {
      element(el) {
        el.setAttribute('content', title);
      }
    })
    .on('meta[property="og:description"]', {
      element(el) {
        el.setAttribute('content', description);
      }
    })
    .on('meta[property="og:url"]', {
      element(el) {
        el.setAttribute('content', url);
      }
    })
    .on('meta[property="og:image"]', {
      element(el) {
        el.setAttribute('content', ogImage);
      }
    })
    .on('meta[property="twitter:title"]', {
      element(el) {
        el.setAttribute('content', title);
      }
    })
    .on('meta[property="twitter:description"]', {
      element(el) {
        el.setAttribute('content', description);
      }
    })
    .on('meta[property="twitter:url"]', {
      element(el) {
        el.setAttribute('content', url);
      }
    })
    .on('meta[property="twitter:image"]', {
      element(el) {
        el.setAttribute('content', ogImage);
      }
    })
    .on('head', {
      element(el) {
        if (headAppended) return;
        headAppended = true;
        // Inject additional OG tags and JSON-LD (not in static HTML)
        el.append(`<meta property="og:site_name" content="Keyboardia" />`, { html: true });
        el.append(`<meta property="og:image:width" content="600" />`, { html: true });
        el.append(`<meta property="og:image:height" content="315" />`, { html: true });
        el.append(generateJsonLd(session, url, baseUrl), { html: true });
      }
    })
    .transform(response);
}

