  REVERB_MIN_DECAY,
  REVERB_MAX_DECAY,
  DELAY_MAX_FEEDBACK,
  CHORUS_MIN_FREQUENCY,
  CHORUS_MAX_FREQUENCY,
} from '../shared/constants';
